fn native_content_process_test_lock() -> &'static Mutex<()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
}

async fn read_http_request(stream: &mut TcpStream) -> String {
    let mut request = Vec::new();
    let mut chunk = [0_u8; 4096];
    loop {
        let read = stream.read(&mut chunk).await.unwrap();
        if read == 0 {
            break;
        }
        request.extend_from_slice(&chunk[..read]);
        let Some(header_end) = request.windows(4).position(|window| window == b"\r\n\r\n") else {
            continue;
        };
        let header_end = header_end + 4;
        let content_length = String::from_utf8_lossy(&request[..header_end])
            .lines()
            .find_map(|line| {
                line.split_once(':').and_then(|(name, value)| {
                    name.eq_ignore_ascii_case("content-length")
                        .then(|| value.trim().parse::<usize>().unwrap())
                })
            })
            .unwrap_or_default();
        if request.len() >= header_end.saturating_add(content_length) {
            break;
        }
    }
    String::from_utf8_lossy(&request).into_owned()
}

fn find_element_with_attribute(
    document: &NativeDocument,
    element_name: &str,
    attribute_name: &str,
    attribute_value: &str,
) -> NativeNodeId {
    let mut pending = vec![document.root()];
    while let Some(id) = pending.pop() {
        let node = document.node(id).unwrap();
        if node.element_name() == Some(element_name)
            && node.attribute(attribute_name) == Some(attribute_value)
        {
            return id;
        }
        pending.extend(node.children().iter().copied());
    }
    panic!("missing {element_name} element with {attribute_name}={attribute_value:?}");
}

#[tokio::test]
async fn native_runtime_session_uses_explicit_local_constructor() {
    let session =
        BrowserRuntimeSession::connect_native(NativeEngineConfig::default().with_initial_url(
            "data:text/html,%3Ctitle%3ERuntime%3C%2Ftitle%3E%3Cp%3ENative%20session%3C%2Fp%3E",
        ))
        .await
        .unwrap();
    assert_eq!(session.runtime(), BrowserRuntime::Native);
    assert_eq!(
        session.profile().identity.backend_id,
        NATIVE_ENGINE_BACKEND_ID
    );

    let evidence = session.evidence(EvidenceLevel::Compact).await.unwrap();
    assert_eq!(
        evidence.url,
        "data:text/html,%3Ctitle%3ERuntime%3C%2Ftitle%3E%3Cp%3ENative%20session%3C%2Fp%3E"
    );
    assert_eq!(evidence.title, "Runtime");
    assert_eq!(evidence.visible_text, "Native session");

    let script = session.script("1 + 1").await.unwrap();
    assert_eq!(script.value, serde_json::json!(2));
    let promise = session.script("await Promise.resolve(42)").await.unwrap();
    assert_eq!(promise.value, serde_json::json!(42));
    let host = session
        .script(
            "({ title: document.title, text: document.querySelector('p').innerText, tag: document.querySelector('p').tagName, width: window.innerWidth, origin: location.origin })",
        )
        .await
        .unwrap();
    assert_eq!(
        host.value,
        serde_json::json!({
            "title": "Runtime",
            "text": "Native session",
            "tag": "P",
            "width": 1280,
            "origin": "null",
        })
    );
    let persisted = session
        .script("globalThis.answer = (globalThis.answer || 0) + 1; globalThis.answer")
        .await
        .unwrap();
    assert_eq!(persisted.value, serde_json::json!(1));
    let persisted = session.script("globalThis.answer").await.unwrap();
    assert_eq!(persisted.value, serde_json::json!(1));
    let storage = session
        .script(
            "localStorage.setItem('theme', 'dark'); sessionStorage.setItem('tab', 'one'); ({ local: localStorage.getItem('theme'), session: sessionStorage.getItem('tab'), localLength: localStorage.length, sessionLength: sessionStorage.length })",
        )
        .await
        .unwrap();
    assert_eq!(
        storage.value,
        serde_json::json!({
            "local": "dark",
            "session": "one",
            "localLength": 1,
            "sessionLength": 1,
        })
    );
    let storage = session
        .script("({ local: localStorage.getItem('theme'), session: sessionStorage.getItem('tab'), localKey: localStorage.key(0), sessionKey: sessionStorage.key(0) })")
        .await
        .unwrap();
    assert_eq!(
        storage.value,
        serde_json::json!({
            "local": "dark",
            "session": "one",
            "localKey": "theme",
            "sessionKey": "tab",
        })
    );
    session
        .script("localStorage.clear(); sessionStorage.removeItem('tab'); true")
        .await
        .unwrap();
    let storage = session
        .script("[localStorage.length, sessionStorage.length]")
        .await
        .unwrap();
    assert_eq!(storage.value, serde_json::json!([0, 0]));
    let stored = session
        .storage(StorageRequest {
            context_id: "native-context".into(),
            scope: StorageScope::Session,
            operation: StorageOperation::Write {
                key: "answer".into(),
                value: "one".into(),
            },
        })
        .await
        .unwrap();
    assert_eq!(stored.entries.get("answer"), Some(&"one".to_owned()));
    session.close().await.unwrap();
}

#[tokio::test]
async fn native_local_inline_page_scripts_run_before_commit_and_persist_realm() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://inline-script-load",
            "<script>globalThis.inlineCount = (globalThis.inlineCount || 0) + 1;</script><script>globalThis.inlineCount += 1; document.getElementById('name').value = 'loaded';</script><input id='name' type='text'>",
        )
        .unwrap()
        .with_initial_url("fixture://inline-script-load");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize_async().await.unwrap();

    assert_eq!(engine.revision(), 1);
    assert_eq!(
        engine
            .evaluate_async("globalThis.inlineCount")
            .await
            .unwrap(),
        serde_json::json!(2)
    );
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('name').value")
            .await
            .unwrap(),
        serde_json::json!("loaded")
    );
    engine.close_async().await.unwrap();
}

