#[tokio::test]
async fn native_child_script_click_owns_external_navigation() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/start", "/destination"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut request = [0_u8; 4096];
            let read = stream.read(&mut request).await.unwrap();
            let request = String::from_utf8_lossy(&request[..read]);
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            let body = if expected_path == "/start" {
                "<title>Start</title><a id='next' href='/destination'>Next</a>".to_owned()
            } else {
                "<title>Destination</title><p>Arrived</p>".to_owned()
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/start")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    let initial_revision = engine.revision();
    engine
        .evaluate_async("document.getElementById('next').click()")
        .await
        .unwrap();
    assert_eq!(engine.revision(), initial_revision + 2);
    assert_eq!(
        engine.snapshot().unwrap().url,
        format!("http://{address}/destination")
    );
    assert_eq!(engine.snapshot().unwrap().title, "Destination");
    assert_eq!(engine.snapshot().unwrap().visible_text, "Arrived");
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_runtime_session_loads_bounded_external_http_html_without_cdp() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for _ in 0..3 {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut request = [0_u8; 4096];
            let read = stream.read(&mut request).await.unwrap();
            let request = String::from_utf8_lossy(&request[..read]);
            let path = request.split_whitespace().nth(1).unwrap_or("/");
            let (status, content_type, location, body) = if path.starts_with("/redirect") {
                ("302 Found", "text/plain", Some("/page"), "")
            } else if path.starts_with("/page") {
                (
                    "200 OK",
                    "text/html; charset=utf-8",
                    None,
                    "<title>Native HTTP</title><p>External native page</p>",
                )
            } else {
                ("200 OK", "application/json", None, "{\"not\":\"html\"}")
            };
            let location_header =
                location.map_or_else(String::new, |value| format!("Location: {value}\r\n"));
            let response = format!(
                "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\n{location_header}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let initial_url = format!("http://{address}/redirect#section");
    let session = BrowserRuntimeSession::connect_native(
        NativeEngineConfig::default().with_initial_url(initial_url),
    )
    .await
    .unwrap();
    let evidence = session.evidence(EvidenceLevel::Compact).await.unwrap();
    assert_eq!(evidence.url, format!("http://{address}/page#section"));
    assert_eq!(evidence.title, "Native HTTP");
    assert_eq!(evidence.visible_text, "External native page");

    let error = session
        .navigate(format!("http://{address}/not-html"))
        .await
        .unwrap_err()
        .to_string();
    assert!(error.contains("unsupported content type"), "{error}");
    session.close().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_evaluates_persistent_script_realm() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let _ = stream.read(&mut request).await.unwrap();
        let body = "<title>Script</title><p>Native script page</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine.evaluate_async("6 * 7").await.unwrap(),
        serde_json::json!(42)
    );
    assert_eq!(
        engine.evaluate_async("document.title").await.unwrap(),
        serde_json::json!("Script")
    );
    assert_eq!(
        engine.evaluate_async("document.readyState").await.unwrap(),
        serde_json::json!("complete")
    );
    assert_eq!(
        engine.evaluate_async("location.origin").await.unwrap(),
        serde_json::json!(format!("http://{address}"))
    );
    assert_eq!(
        engine
            .evaluate_async("document.querySelector('p').textContent")
            .await
            .unwrap(),
        serde_json::json!("Native script page")
    );
    assert_eq!(
        engine
            .evaluate_async("await Promise.resolve(42)")
            .await
            .unwrap(),
        serde_json::json!(42)
    );
    assert_eq!(
        engine
            .evaluate_async("globalThis.answer = (globalThis.answer || 0) + 1; answer")
            .await
            .unwrap(),
        serde_json::json!(1)
    );
    assert_eq!(
        engine.evaluate_async("answer").await.unwrap(),
        serde_json::json!(1)
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_runs_inline_page_scripts_in_persistent_realm() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let _ = stream.read(&mut request).await.unwrap();
        let body = "<script>globalThis.inlineCount = (globalThis.inlineCount || 0) + 1; globalThis.lifecycle = []; document.addEventListener('readystatechange', () => lifecycle.push('ready:' + document.readyState)); document.addEventListener('DOMContentLoaded', () => lifecycle.push('dom:' + document.readyState)); addEventListener('load', () => lifecycle.push('load:' + document.readyState));</script><script>globalThis.inlineCount += 1; document.getElementById('name').value = 'loaded';</script><input id='name' type='text'>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/page")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    assert_eq!(
        engine
            .evaluate_async("globalThis.inlineCount")
            .await
            .unwrap(),
        serde_json::json!(2)
    );
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('name').value")
            .await
            .unwrap(),
        serde_json::json!("loaded")
    );
    assert_eq!(
        engine.evaluate_async("globalThis.lifecycle").await.unwrap(),
        serde_json::json!([
            "ready:interactive",
            "dom:interactive",
            "ready:complete",
            "load:complete"
        ])
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[tokio::test]
async fn native_content_process_orders_navigation_lifecycle_events() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        for expected_path in ["/old", "/next"] {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut request = [0_u8; 4096];
            let read = stream.read(&mut request).await.unwrap();
            let request = String::from_utf8_lossy(&request[..read]);
            assert_eq!(request.split_whitespace().nth(1), Some(expected_path));
            let body = if expected_path == "/old" {
                "<script>addEventListener('pagehide', () => globalThis.oldPagehide = true); addEventListener('unload', () => globalThis.oldUnload = true);</script><p>Old</p>"
            } else {
                "<script>globalThis.lifecycle = []; addEventListener('pageshow', () => lifecycle.push(document.readyState));</script><p>Next</p>"
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(response.as_bytes()).await.unwrap();
        }
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/old")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    let before_navigation = engine.revision();
    engine
        .navigate_async(format!("http://{address}/next"))
        .await
        .unwrap();
    assert_eq!(
        engine.evaluate_async("globalThis.lifecycle").await.unwrap(),
        serde_json::json!(["complete"])
    );
    let lifecycle_effects = engine
        .effects_since(before_navigation)
        .unwrap()
        .effects
        .into_iter()
        .map(|effect| effect.kind)
        .filter(|kind| {
            matches!(
                kind,
                NativeEventKind::PageHide | NativeEventKind::Unload | NativeEventKind::PageShow
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        lifecycle_effects,
        vec![
            NativeEventKind::PageHide,
            NativeEventKind::Unload,
            NativeEventKind::PageShow
        ]
    );
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

