#[tokio::test]
async fn native_content_process_owns_external_form_mutations_and_effects() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let _ = stream.read(&mut request).await.unwrap();
        let body = "<input id='toggle' type='checkbox' style='width:80px;height:20px'><input id='name' type='text' style='width:120px;height:20px'>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/form")),
    )
    .unwrap();
    engine.initialize_async().await.unwrap();
    let initial_revision = engine.revision();

    let clicked = engine
        .action_async(NativeAction::Click {
            target: "id=toggle".into(),
        })
        .await
        .unwrap();
    assert!(clicked.accepted);
    assert_eq!(clicked.revision, initial_revision + 1);
    let toggle = engine
        .semantic_nodes()
        .unwrap()
        .into_iter()
        .find(|node| node.input_type.as_deref() == Some("checkbox"))
        .unwrap();
    assert_eq!(toggle.checked, Some(true));

    let typed = engine
        .action_async(NativeAction::Type {
            target: "id=name".into(),
            text: "secret-value".into(),
        })
        .await
        .unwrap();
    assert!(typed.accepted);
    assert_eq!(typed.revision, clicked.revision + 1);
    let input = engine
        .semantic_nodes()
        .unwrap()
        .into_iter()
        .find(|node| node.input_type.as_deref() == Some("text"))
        .unwrap();
    assert_eq!(input.empty, Some(false));
    assert!(input.focused);

    let effects = engine.effects_since(initial_revision).unwrap();
    assert_eq!(effects.revision, typed.revision);
    assert!(effects.changed);
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::Click)
    );
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::Input)
    );
    assert!(
        effects
            .effects
            .iter()
            .any(|effect| effect.kind == NativeEventKind::Change)
    );
    let encoded_effects = format!("{:?}", effects.effects);
    assert!(!encoded_effects.contains("secret-value"));

    let scripted = engine
        .evaluate_async(
            "const toggle = document.getElementById('toggle'); const input = document.getElementById('name'); toggle.click(); input.value = 'child-value'; input.setAttribute('data-source', 'script'); ({ checked: toggle.checked, value: input.value, source: input.getAttribute('data-source') })",
        )
        .await
        .unwrap();
    assert_eq!(
        scripted,
        serde_json::json!({
            "checked": false,
            "value": "child-value",
            "source": "script",
        })
    );
    assert_eq!(engine.revision(), typed.revision + 1);
    assert_eq!(
        engine
            .evaluate_async(
                "({ checked: document.getElementById('toggle').checked, value: document.getElementById('name').value, source: document.getElementById('name').getAttribute('data-source') })",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "checked": false,
            "value": "child-value",
            "source": "script",
        })
    );

    let listener_revision = engine.revision();
    let prevented = engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); globalThis.childEvents = []; globalThis.childClick = (event) => { globalThis.childEvents.push(event.type + ':' + event.target.id); document.getElementById('name').value = 'event-child'; event.preventDefault(); }; toggle.addEventListener('click', globalThis.childClick); toggle.click(); return { checked: toggle.checked, value: document.getElementById('name').value, events: globalThis.childEvents }; })()",
        )
        .await
        .unwrap();
    assert_eq!(
        prevented,
        serde_json::json!({
            "checked": false,
            "value": "event-child",
            "events": ["click:toggle"],
        })
    );
    assert_eq!(engine.revision(), listener_revision + 1);

    let accepted = engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); toggle.removeEventListener('click', globalThis.childClick); toggle.click(); return toggle.checked; })()",
        )
        .await
        .unwrap();
    assert_eq!(accepted, serde_json::json!(true));
    assert_eq!(engine.revision(), listener_revision + 2);

    let before_action = engine.revision();
    engine
        .evaluate_async(
            "(() => { globalThis.onChildAction = (event) => { document.getElementById('name').value = 'action-child'; }; document.getElementById('toggle').addEventListener('click', globalThis.onChildAction); })()",
        )
        .await
        .unwrap();
    let action = engine
        .action_async(NativeAction::Click {
            target: "id=toggle".into(),
        })
        .await
        .unwrap();
    assert!(action.accepted);
    assert_eq!(action.revision, before_action + 1);
    assert_eq!(engine.revision(), before_action + 1);
    assert_eq!(
        engine
            .evaluate_async(
                "({ checked: document.getElementById('toggle').checked, value: document.getElementById('name').value })",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "checked": false,
            "value": "action-child",
        })
    );
    let before_cancel = engine.revision();
    engine
        .evaluate_async(
            "(() => { const toggle = document.getElementById('toggle'); toggle.removeEventListener('click', globalThis.onChildAction); globalThis.onChildCancel = (event) => event.preventDefault(); toggle.addEventListener('click', globalThis.onChildCancel); })()",
        )
        .await
        .unwrap();
    let canceled = engine
        .action_async(NativeAction::Click {
            target: "id=toggle".into(),
        })
        .await
        .unwrap();
    assert!(canceled.accepted);
    assert_eq!(canceled.revision, before_cancel + 1);
    assert_eq!(engine.revision(), before_cancel + 1);
    assert_eq!(
        engine
            .evaluate_async("document.getElementById('toggle').checked")
            .await
            .unwrap(),
        serde_json::json!(false)
    );
    let before_type = engine.revision();
    engine
        .evaluate_async(
            "(() => { const field = document.getElementById('name'); globalThis.childTypeEvents = []; field.addEventListener('focus', (event) => globalThis.childTypeEvents.push(event.type)); field.addEventListener('input', (event) => { globalThis.childTypeEvents.push(event.type); field.setAttribute('data-input', 'seen'); }); field.addEventListener('change', (event) => globalThis.childTypeEvents.push(event.type)); })()",
        )
        .await
        .unwrap();
    let typed = engine
        .action_async(NativeAction::Type {
            target: "id=name".into(),
            text: "typed-by-child-action".into(),
        })
        .await
        .unwrap();
    assert!(typed.accepted);
    assert_eq!(typed.revision, before_type + 1);
    assert_eq!(engine.revision(), before_type + 1);
    assert_eq!(
        engine
            .evaluate_async(
                "({ value: document.getElementById('name').value, marker: document.getElementById('name').getAttribute('data-input'), events: globalThis.childTypeEvents })",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "value": "typed-by-child-action",
            "marker": "seen",
            "events": ["focus", "input", "change"],
        })
    );

    engine
        .evaluate_async(
            "(() => { const field = document.getElementById('name'); globalThis.childKeyEvents = []; field.addEventListener('keydown', event => globalThis.childKeyEvents.push(event.type + ':' + event.key)); field.addEventListener('input', event => globalThis.childKeyEvents.push(event.type + ':' + field.value)); field.addEventListener('keyup', event => globalThis.childKeyEvents.push(event.type + ':' + event.key)); })()",
        )
        .await
        .unwrap();
    let keyed = engine
        .action_async(NativeAction::KeyPress { key: "!".into() })
        .await
        .unwrap();
    assert!(keyed.accepted);
    assert_eq!(
        engine
            .evaluate_async(
                "({ value: document.getElementById('name').value, events: globalThis.childKeyEvents })",
            )
            .await
            .unwrap(),
        serde_json::json!({
            "value": "typed-by-child-action!",
            "events": ["keydown:!", "input:typed-by-child-action!", "keyup:!"],
        })
    );

    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[cfg(unix)]
#[tokio::test]
async fn native_content_process_recovers_after_worker_exit_during_startup() {
    let _guard = native_content_process_test_lock().lock().await;
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let server = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await.unwrap();
        let mut request = [0_u8; 4096];
        let _ = stream.read(&mut request).await.unwrap();
        let body = "<title>Recovered</title><p>Fresh child</p>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(response.as_bytes()).await.unwrap();
    });

    let previous_worker = std::env::var_os("GLASS_NATIVE_CONTENT_WORKER");
    // `/bin/false` exits before answering the first ping. This is an isolated
    // startup-failure injection; the test restores the process environment
    // before asking the still-New engine to initialize again.
    unsafe {
        std::env::set_var("GLASS_NATIVE_CONTENT_WORKER", "/bin/false");
    }
    let mut engine = NativeEngine::new(
        NativeEngineConfig::default().with_initial_url(format!("http://{address}/recover")),
    )
    .unwrap();
    let first_error = engine.initialize_async().await.unwrap_err();
    assert!(matches!(
        first_error,
        NativeEngineError::WorkerFailure {
            kind: NativeWorkerFailureKind::Exited | NativeWorkerFailureKind::Transport,
            ..
        }
    ));
    unsafe {
        if let Some(previous_worker) = previous_worker {
            std::env::set_var("GLASS_NATIVE_CONTENT_WORKER", previous_worker);
        } else {
            std::env::remove_var("GLASS_NATIVE_CONTENT_WORKER");
        }
    }

    engine.initialize_async().await.unwrap();
    let evidence = engine.snapshot().unwrap();
    assert_eq!(evidence.title, "Recovered");
    engine.close_async().await.unwrap();
    server.await.unwrap();
}

#[test]
fn native_layout_is_deterministic_and_uses_bounded_pixel_dimensions() {
    let document = NativeDocument::parse(
        "<style>button { width: 120px; height: 32px; }</style><main><button id='first'>First</button><button id='second' style='display:block;width:140px'>Second</button><p id='below'>Below</p></main>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 320,
        height: 200,
        device_scale_factor_milli: 1000,
    };
    let first = document.resolve_target("id=first").unwrap();
    let second = document.resolve_target("id=second").unwrap();
    let below = document.resolve_target("id=below").unwrap();
    let expected_first = NativeRect {
        x: 0,
        y: 0,
        width: 120,
        height: 32,
    };
    let expected_second = NativeRect {
        x: 0,
        y: 32,
        width: 140,
        height: 32,
    };
    let layout = document.layout(viewport).unwrap();
    assert_eq!(layout.revision, 1);
    assert_eq!(layout.box_for(first), Some(expected_first));
    assert_eq!(layout.box_for(second), Some(expected_second));
    assert_eq!(
        layout.box_for(below),
        Some(NativeRect {
            x: 0,
            y: 64,
            width: 320,
            height: 20,
        })
    );
    assert_eq!(layout, document.layout(viewport).unwrap());
}

#[test]
fn native_layout_excludes_hidden_boxes_and_hit_testing_is_viewport_bound() {
    let document = NativeDocument::parse(
        "<style>.gone { display:none } .also-gone { visibility:hidden }</style><main><button class='gone' id='hidden'>Hidden</button><button class='also-gone' id='also-hidden'>Also hidden</button><button id='shown'>Shown</button></main>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 320,
        height: 200,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();
    assert_eq!(
        layout.box_for(document.resolve_target("id=hidden").unwrap()),
        None
    );
    assert_eq!(
        layout.box_for(document.resolve_target("id=also-hidden").unwrap()),
        None
    );
    let shown = document.resolve_target("id=shown").unwrap();
    let shown_rect = layout.box_for(shown).unwrap();
    assert_eq!(
        layout
            .hit_test(i64::from(shown_rect.x), i64::from(shown_rect.y))
            .unwrap(),
        Some(shown)
    );
    assert!(layout.hit_test(-1, 0).is_err());
    assert!(layout.hit_test(320, 0).is_err());
}

#[test]
fn native_vertical_scroll_maps_layout_hit_testing_and_raster_output() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 80,
            height: 24,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://scroll",
            "<div id='top' style='display:block;height:24px;background-color:red'>Top</div><button id='bottom' style='display:block;height:24px;background-color:blue'>Bottom</button>",
        )
        .unwrap()
        .with_initial_url("fixture://scroll");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let bottom = engine
        .semantic_nodes()
        .unwrap()
        .into_iter()
        .find(|node| node.name == "Bottom")
        .unwrap();
    let initial = engine.layout().unwrap();
    assert_eq!(initial.scroll_offset, NativePoint { x: 0, y: 0 });
    assert!(initial.content_height > initial.viewport.height);
    assert_eq!(initial.viewport_rect_for(bottom.node_id), None);

    let scrolled = engine
        .action(NativeAction::Scroll {
            delta_x: 0,
            delta_y: i32::MAX,
        })
        .unwrap();
    assert!(scrolled.accepted);
    assert_eq!(scrolled.revision, 2);
    let layout = engine.layout().unwrap();
    assert_eq!(layout.scroll_offset, layout.max_scroll_offset());
    assert_eq!(layout.viewport_rect_for(bottom.node_id).unwrap().y, 0);
    assert_eq!(engine.hit_test(1, 1).unwrap(), Some(bottom.node_id));
    assert_eq!(
        engine
            .effects_since(1)
            .unwrap()
            .effects
            .iter()
            .map(|effect| effect.kind)
            .collect::<Vec<_>>(),
        vec![NativeEventKind::Scroll]
    );

    let list = engine.display_list().unwrap();
    assert_eq!(list.scroll_offset, layout.scroll_offset);
    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(1, 1), Some([0, 0, 255, 255]));

    let clicked = engine
        .action(NativeAction::Click {
            target: "id=bottom".into(),
        })
        .unwrap();
    assert!(clicked.accepted);
    assert_eq!(clicked.revision, 3);

    let no_op = engine
        .action(NativeAction::Scroll {
            delta_x: 0,
            delta_y: i32::MAX,
        })
        .unwrap();
    assert!(!no_op.accepted);
    assert_eq!(no_op.revision, 3);
    assert_eq!(engine.scroll_offset(), layout.scroll_offset);

    let horizontal_edge = engine
        .action(NativeAction::Scroll {
            delta_x: 1,
            delta_y: 0,
        })
        .unwrap();
    assert!(!horizontal_edge.accepted);
    assert_eq!(engine.revision(), 3);
}

#[test]
fn native_horizontal_scroll_projects_wide_preformatted_content_and_history() {
    let config = NativeEngineConfig::default()
        .with_viewport(Viewport {
            width: 16,
            height: 24,
            device_scale_factor_milli: 1000,
        })
        .with_fixture(
            "fixture://wide",
            "<pre id='wide' style='white-space:pre'>A A</pre><div id='below' style='display:block;height:40px'>Below</div><pre style='display:none;white-space:pre'>Hidden hidden hidden</pre><script>Invisible invisible invisible</script>",
        )
        .unwrap()
        .with_fixture("fixture://narrow", "<p>Narrow</p>")
        .unwrap()
        .with_initial_url("fixture://wide");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let initial = engine.layout().unwrap();
    let wide_text = initial
        .text_runs
        .iter()
        .find(|run| run.text == "A A")
        .unwrap();
    let wide = wide_text.node_id;
    assert_eq!(initial.content_width, 24);
    assert_eq!(initial.max_scroll_offset(), NativePoint { x: 8, y: 36 });
    assert_eq!(initial.scroll_offset, NativePoint { x: 0, y: 0 });
    assert_eq!(wide_text.origin, NativePoint { x: 0, y: 0 });
    assert!(!wide_text.truncated);
    assert_eq!(initial.viewport_rect_for(wide).unwrap().width, 16);

    let unscrolled = engine.rasterize().unwrap();
    assert_eq!(unscrolled.pixel(1, 0), Some([0, 0, 0, 255]));

    let horizontal = engine
        .action(NativeAction::Scroll {
            delta_x: i32::MAX,
            delta_y: 0,
        })
        .unwrap();
    assert!(horizontal.accepted);
    assert_eq!(horizontal.revision, 2);
    assert_eq!(engine.scroll_offset(), NativePoint { x: 8, y: 0 });
    let horizontal_layout = engine.layout().unwrap();
    assert_eq!(
        horizontal_layout.max_scroll_offset(),
        NativePoint { x: 8, y: 36 }
    );
    assert_eq!(
        horizontal_layout.viewport_rect_for(wide),
        Some(NativeRect {
            x: 0,
            y: 0,
            width: 8,
            height: 20,
        })
    );
    assert_eq!(engine.hit_test(1, 0).unwrap(), Some(wide));
    assert_eq!(engine.display_list().unwrap().scroll_offset.x, 8);
    assert_eq!(
        engine.rasterize().unwrap().pixel(1, 0),
        Some([255, 255, 255, 255])
    );

    let diagonal = engine
        .action(NativeAction::Scroll {
            delta_x: -4,
            delta_y: i32::MAX,
        })
        .unwrap();
    assert!(diagonal.accepted);
    assert_eq!(diagonal.revision, 3);
    assert_eq!(engine.scroll_offset(), NativePoint { x: 4, y: 36 });

    let edge = engine
        .action(NativeAction::Scroll {
            delta_x: i32::MAX,
            delta_y: i32::MAX,
        })
        .unwrap();
    assert!(edge.accepted);
    assert_eq!(edge.revision, 4);
    assert_eq!(engine.scroll_offset(), NativePoint { x: 8, y: 36 });

    let no_op = engine
        .action(NativeAction::Scroll {
            delta_x: i32::MAX,
            delta_y: i32::MAX,
        })
        .unwrap();
    assert!(!no_op.accepted);
    assert_eq!(no_op.revision, 4);

    let saved = engine.scroll_offset();
    engine.navigate("fixture://narrow").unwrap();
    assert_eq!(engine.scroll_offset(), NativePoint { x: 0, y: 0 });
    engine.go_back().unwrap().unwrap();
    assert_eq!(engine.scroll_offset(), saved);
}

#[test]
fn native_root_overflow_ignores_fully_clipped_text_but_keeps_visible_text_extent() {
    let document = NativeDocument::parse(
        "<div id='clipped' style='display:block;width:16px;overflow:hidden;white-space:nowrap'>ABCDEFG</div><div id='visible' style='display:block;white-space:nowrap'>ABCD</div><div id='clip' style='display:block;width:16px;overflow:clip;white-space:nowrap'>HIJKLMN</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 24,
        height: 80,
        device_scale_factor_milli: 1000,
    };
    let clipped = document.resolve_target("id=clipped").unwrap();
    let visible = document.resolve_target("id=visible").unwrap();
    let clip = document.resolve_target("id=clip").unwrap();
    let layout = document.layout(viewport).unwrap();

    assert_eq!(layout.box_for(clipped).unwrap().width, 16);
    assert_eq!(layout.box_for(clip).unwrap().width, 16);
    assert_eq!(layout.box_for(visible).unwrap().width, 24);
    assert_eq!(layout.content_width, 32);
    assert_eq!(layout.max_scroll_offset().x, 8);
    assert!(
        layout
            .text_runs
            .iter()
            .any(|run| run.node_id == clipped && run.text == "ABCDEFG")
    );
    assert!(
        layout
            .text_runs
            .iter()
            .any(|run| run.node_id == clip && run.text == "HIJKLMN")
    );

    let clipped_only = NativeDocument::parse(
        "<div id='clipped' style='display:block;width:16px;overflow:hidden;white-space:nowrap'>ABCDEFG</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let clipped_only_layout = clipped_only.layout(viewport).unwrap();
    assert_eq!(clipped_only_layout.content_width, viewport.width);
    assert_eq!(clipped_only_layout.max_scroll_offset().x, 0);
}

#[test]
fn native_display_list_is_revisioned_deterministic_and_visibility_aware() {
    let document = NativeDocument::parse(
        "<style>#card { background-color: #102030; color: rgb(1, 2, 3); }</style><main><div id='card'>Hello <span>child</span></div><div id='hidden' style='display:none;background-color:red'>Hidden</div></main>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 320,
        height: 200,
        device_scale_factor_milli: 1000,
    };
    let card = document.resolve_target("id=card").unwrap();
    let hidden = document.resolve_target("id=hidden").unwrap();

    let list = document.display_list(viewport).unwrap();
    assert_eq!(list.revision, document.revision());
    assert_eq!(list.viewport, viewport);
    assert!(matches!(
        list.commands.first(),
        Some(NativeDisplayCommand::Clear { color }) if *color == NativeColor::WHITE
    ));
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, color, .. }
                if *node_id == card
                    && *color == NativeColor { red: 16, green: 32, blue: 48, alpha: 255 }
        )
    }));
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::TextRun { text, color, .. }
                if text == "Hello"
                    && *color == NativeColor { red: 1, green: 2, blue: 3, alpha: 255 }
        )
    }));
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::TextRun { text, color, .. }
                if text == "child"
                    && *color == NativeColor { red: 1, green: 2, blue: 3, alpha: 255 }
        )
    }));
    assert!(!list.commands.iter().any(|command| match command {
        NativeDisplayCommand::FillRect { node_id, .. }
        | NativeDisplayCommand::BorderRect { node_id, .. }
        | NativeDisplayCommand::TextRun { node_id, .. } => *node_id == hidden,
        NativeDisplayCommand::BeginOpacityGroup { .. }
        | NativeDisplayCommand::Clear { .. }
        | NativeDisplayCommand::EndOpacityGroup { .. } => false,
    }));
    assert_eq!(list, document.display_list(viewport).unwrap());
}

#[test]
fn native_display_visibility_revert_layer_preserves_hidden_subtree_owners() {
    let document = NativeDocument::parse(
        "<style>@layer base { #rolled { display:none;visibility:hidden;width:12px;height:8px;background-color:red; } #repeat { display:block;visibility:visible;width:12px;height:8px;background-color:red; } #contents { display:contents;visibility:visible; } #fallback { display:revert-layer;visibility:revert-layer;width:12px;height:8px;background-color:green; } #inline { display:block;visibility:hidden;width:12px;height:8px;background-color:yellow; } #child { display:block;width:12px;height:8px;background-color:blue; } } @layer theme { #rolled { display:block;visibility:visible; } #rolled { display:revert-layer;visibility:revert-layer; } #repeat { display:revert-layer;visibility:revert-layer; } #contents { display:block;visibility:hidden; } #contents { display:revert-layer;visibility:revert-layer; } } @layer top { #repeat { display:revert-layer;visibility:revert-layer; } } #rolled { display:revert-layer;visibility:revert-layer; } #repeat { display:revert-layer;visibility:revert-layer; } #contents { display:revert-layer;visibility:revert-layer; }</style><button id='rolled'>Rolled</button><button id='repeat'>Repeat</button><div id='contents'><button id='child'>Child</button></div><button id='fallback'>Fallback</button><button id='inline' style='display:ReVeRt-LaYeR;visibility:revert-layer'>Inline</button>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 24,
        height: 32,
        device_scale_factor_milli: 1000,
    };
    let rolled = document.resolve_target("id=rolled").unwrap();
    let repeat = document.resolve_target("id=repeat").unwrap();
    let contents = document.resolve_target("id=contents").unwrap();
    let child = document.resolve_target("id=child").unwrap();
    let fallback = document.resolve_target("id=fallback").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();

    let layout = document.layout(viewport).unwrap();
    assert_eq!(layout.box_for(rolled), None);
    assert_eq!(layout.box_for(contents), None);
    assert_eq!(
        layout.box_for(repeat),
        Some(NativeRect {
            x: 0,
            y: 0,
            width: 12,
            height: 8,
        })
    );
    assert_eq!(layout.box_for(child).unwrap().y, 8);
    assert_eq!(layout.box_for(fallback).unwrap().y, 16);
    assert_eq!(layout.box_for(inline), None);
    assert_eq!(layout.hit_test(1, 1).unwrap(), Some(repeat));
    assert_eq!(layout.hit_test(1, 9).unwrap(), Some(child));
    assert_eq!(layout.hit_test(1, 17).unwrap(), Some(fallback));

    let semantic_nodes = document.semantic_nodes();
    assert!(
        semantic_nodes
            .iter()
            .any(|node| node.node_id == rolled && node.hidden)
    );
    assert!(
        semantic_nodes
            .iter()
            .any(|node| node.node_id == repeat && !node.hidden)
    );
    assert!(
        semantic_nodes
            .iter()
            .any(|node| node.node_id == child && !node.hidden)
    );
    assert!(
        semantic_nodes
            .iter()
            .any(|node| node.node_id == fallback && !node.hidden)
    );
    assert!(
        semantic_nodes
            .iter()
            .any(|node| node.node_id == inline && node.hidden)
    );

    let list = document.display_list(viewport).unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, color, .. }
                if *node_id == repeat && *color == NativeColor::RED
        )
    }));
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, color, .. }
                if *node_id == child && *color == NativeColor { red: 0, green: 0, blue: 255, alpha: 255 }
        )
    }));
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, color, .. }
                if *node_id == fallback && *color == NativeColor { red: 0, green: 128, blue: 0, alpha: 255 }
        )
    }));
    assert!(!list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, .. }
                | NativeDisplayCommand::BorderRect { node_id, .. }
                | NativeDisplayCommand::TextRun { node_id, .. }
                if *node_id == rolled || *node_id == inline
        )
    }));
    assert!(!document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && matches!(diagnostic.detail.as_str(), "display" | "visibility")
    }));

    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(1, 1), Some([255, 0, 0, 255]));
    assert_eq!(surface.pixel(1, 9), Some([0, 0, 255, 255]));
    assert_eq!(surface.pixel(1, 17), Some([0, 128, 0, 255]));
}

#[test]
fn native_border_revert_layer_preserves_side_geometry_and_artifacts() {
    let document = NativeDocument::parse(
        "<style>@layer base { #card { display:block;width:8px;height:6px;border:1px solid red; } #sides { display:block;width:8px;height:6px;border-top:1px solid red;border-right:2px solid green;border-bottom:3px solid blue;border-left:4px solid black; } #fallback { display:block;width:8px;height:6px;border:revert-layer;background-color:yellow; } #inline { display:block;width:8px;height:6px;border:1px solid red; } } @layer theme { #card { border:3px dashed blue; } #card { border:revert-layer; } #sides { border-top:5px dotted green;border-right:6px solid blue;border-bottom:7px dashed black;border-left:8px solid red; } #sides { border-top:revert-layer;border-bottom:revert-layer; } #inline { border:3px solid green; } } #card { border:revert-layer; } #sides { border-top:revert-layer;border-right:revert-layer;border-left:revert-layer; }</style><button id='card'>Card</button><button id='sides'>Sides</button><button id='fallback'>Fallback</button><button id='inline' style='border:ReVeRt-LaYeR'>Inline</button>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 40,
        device_scale_factor_milli: 1000,
    };
    let card = document.resolve_target("id=card").unwrap();
    let sides = document.resolve_target("id=sides").unwrap();
    let fallback = document.resolve_target("id=fallback").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();

    let layout = document.layout(viewport).unwrap();
    assert_eq!(
        layout.box_for(card),
        Some(NativeRect {
            x: 0,
            y: 0,
            width: 10,
            height: 8,
        })
    );
    assert_eq!(
        layout.box_for(sides),
        Some(NativeRect {
            x: 0,
            y: 8,
            width: 22,
            height: 10,
        })
    );
    assert_eq!(
        layout.box_for(fallback),
        Some(NativeRect {
            x: 0,
            y: 18,
            width: 8,
            height: 6,
        })
    );
    assert_eq!(
        layout.box_for(inline),
        Some(NativeRect {
            x: 0,
            y: 24,
            width: 14,
            height: 12,
        })
    );
    assert_eq!(layout.hit_test(2, 2).unwrap(), Some(card));
    assert_eq!(layout.hit_test(10, 12).unwrap(), Some(sides));
    assert_eq!(layout.hit_test(1, 19).unwrap(), Some(fallback));
    assert_eq!(layout.hit_test(5, 28).unwrap(), Some(inline));

    let semantic_nodes = document.semantic_nodes();
    for node_id in [card, sides, fallback, inline] {
        assert!(
            semantic_nodes
                .iter()
                .any(|node| node.node_id == node_id && !node.hidden),
            "expected border fixture node {node_id:?} to remain visible"
        );
    }

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    let card_border = border_for(card).expect("card border command");
    assert_eq!(card_border.top.width, 1);
    assert_eq!(card_border.top.style, NativeBorderStyle::Solid);
    assert_eq!(card_border.top.color, NativeColor::RED);
    assert_eq!(card_border.right, card_border.top);
    assert_eq!(card_border.bottom, card_border.top);
    assert_eq!(card_border.left, card_border.top);

    let sides_border = border_for(sides).expect("side border command");
    assert_eq!(sides_border.top.width, 1);
    assert_eq!(sides_border.top.style, NativeBorderStyle::Solid);
    assert_eq!(sides_border.top.color, NativeColor::RED);
    assert_eq!(sides_border.right.width, 6);
    assert_eq!(sides_border.right.style, NativeBorderStyle::Solid);
    assert_eq!(
        sides_border.right.color,
        NativeColor {
            red: 0,
            green: 0,
            blue: 255,
            alpha: 255,
        }
    );
    assert_eq!(sides_border.bottom.width, 3);
    assert_eq!(sides_border.bottom.style, NativeBorderStyle::Solid);
    assert_eq!(
        sides_border.bottom.color,
        NativeColor {
            red: 0,
            green: 0,
            blue: 255,
            alpha: 255,
        }
    );
    assert_eq!(sides_border.left.width, 8);
    assert_eq!(sides_border.left.style, NativeBorderStyle::Solid);
    assert_eq!(sides_border.left.color, NativeColor::RED);
    assert!(border_for(fallback).is_none());

    let inline_border = border_for(inline).expect("inline border command");
    assert_eq!(inline_border.top.width, 3);
    assert_eq!(inline_border.top.style, NativeBorderStyle::Solid);
    assert_eq!(
        inline_border.top.color,
        NativeColor {
            red: 0,
            green: 128,
            blue: 0,
            alpha: 255,
        }
    );
    assert_eq!(inline_border.right, inline_border.top);
    assert_eq!(inline_border.bottom, inline_border.top);
    assert_eq!(inline_border.left, inline_border.top);
    assert!(!document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && matches!(
                diagnostic.detail.as_str(),
                "border" | "border-top" | "border-right" | "border-bottom" | "border-left"
            )
    }));

    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(0, 0), Some([255, 0, 0, 255]));
    assert_eq!(surface.pixel(10, 8), Some([255, 0, 0, 255]));
    assert_eq!(surface.pixel(21, 12), Some([0, 0, 255, 255]));
    assert_eq!(surface.pixel(10, 17), Some([0, 0, 255, 255]));
    assert_eq!(surface.pixel(0, 12), Some([255, 0, 0, 255]));
    assert_eq!(surface.pixel(5, 24), Some([0, 128, 0, 255]));
    assert!(!surface.to_png().unwrap().is_empty());
}

#[test]
fn native_border_color_revert_layer_preserves_component_geometry_and_artifacts() {
    let document = NativeDocument::parse(
        "<style>@layer base { #shorthand { display:block;width:8px;height:6px;border:1px solid red; } #sides { display:block;width:8px;height:6px;border:2px dashed red; } #repeat { display:block;width:8px;height:6px;border:1px solid red; } #fallback { display:block;width:8px;height:6px;border:1px solid red; } #same { display:block;width:8px;height:6px;border:1px solid red;border-color:revert-layer; } #inline { display:block;width:8px;height:6px;border:1px solid red; } #order-a { display:block;width:8px;height:6px;border-color:blue;border:1px solid red; } #order-b { display:block;width:8px;height:6px;border:1px solid red;border-color:blue; } } @layer theme { #shorthand { border-color:blue green blue black; } #sides { border-top-color:blue;border-right-color:green;border-bottom-color:blue;border-left-color:black; } #sides { border-top-color:revert-layer;border-bottom-color:revert-layer; } #repeat { border-color:blue; } #repeat { border-color:revert-layer; } #fallback { border-color:revert-layer; } #inline { border-color:blue; } } @layer top { #repeat { border-color:revert-layer; } } #shorthand { border-color:revert-layer; } #repeat { border-color:revert-layer; }</style><button id='shorthand'>Shorthand</button><button id='sides'>Sides</button><button id='repeat'>Repeat</button><button id='fallback'>Fallback</button><button id='same'>Same</button><button id='inline' style='border-color:revert-layer'>Inline</button><button id='order-a'>Order A</button><button id='order-b'>Order B</button>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 72,
        device_scale_factor_milli: 1000,
    };
    let shorthand = document.resolve_target("id=shorthand").unwrap();
    let sides = document.resolve_target("id=sides").unwrap();
    let repeat = document.resolve_target("id=repeat").unwrap();
    let fallback = document.resolve_target("id=fallback").unwrap();
    let same = document.resolve_target("id=same").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let order_a = document.resolve_target("id=order-a").unwrap();
    let order_b = document.resolve_target("id=order-b").unwrap();

    let layout = document.layout(viewport).unwrap();
    assert_eq!(layout.box_for(shorthand).unwrap().width, 10);
    assert_eq!(layout.box_for(shorthand).unwrap().height, 8);
    assert_eq!(layout.box_for(sides).unwrap().width, 12);
    assert_eq!(layout.box_for(sides).unwrap().height, 10);
    for node_id in [
        shorthand, sides, repeat, fallback, same, inline, order_a, order_b,
    ] {
        let rectangle = layout.box_for(node_id).expect("border-color layout box");
        assert_eq!(
            layout
                .hit_test((rectangle.x + 1).into(), (rectangle.y + 1).into())
                .unwrap(),
            Some(node_id)
        );
    }

    let semantic_nodes = document.semantic_nodes();
    for node_id in [
        shorthand, sides, repeat, fallback, same, inline, order_a, order_b,
    ] {
        assert!(
            semantic_nodes
                .iter()
                .any(|node| node.node_id == node_id && !node.hidden),
            "expected border-color fixture node {node_id:?} to remain visible"
        );
    }

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    let shorthand_border = border_for(shorthand).expect("shorthand border command");
    assert_eq!(
        shorthand_border.top.color,
        NativeColor {
            red: 0,
            green: 0,
            blue: 255,
            alpha: 255
        }
    );
    assert_eq!(
        shorthand_border.right.color,
        NativeColor {
            red: 0,
            green: 128,
            blue: 0,
            alpha: 255
        }
    );
    assert_eq!(
        shorthand_border.bottom.color,
        NativeColor {
            red: 0,
            green: 0,
            blue: 255,
            alpha: 255
        }
    );
    assert_eq!(shorthand_border.left.color, NativeColor::BLACK);
    assert_eq!(shorthand_border.top.width, 1);
    assert_eq!(shorthand_border.top.style, NativeBorderStyle::Solid);

    let sides_border = border_for(sides).expect("physical color longhand command");
    assert_eq!(sides_border.top.color, NativeColor::RED);
    assert_eq!(
        sides_border.right.color,
        NativeColor {
            red: 0,
            green: 128,
            blue: 0,
            alpha: 255
        }
    );
    assert_eq!(sides_border.bottom.color, NativeColor::RED);
    assert_eq!(sides_border.left.color, NativeColor::BLACK);
    assert_eq!(sides_border.top.width, 2);
    assert_eq!(sides_border.top.style, NativeBorderStyle::Dashed);

    assert_eq!(border_for(repeat).unwrap().top.color, NativeColor::RED);
    assert_eq!(border_for(fallback).unwrap().top.color, NativeColor::RED);
    assert_eq!(border_for(same).unwrap().top.color, NativeColor::BLACK);
    assert_eq!(
        border_for(inline).unwrap().top.color,
        NativeColor {
            red: 0,
            green: 0,
            blue: 255,
            alpha: 255
        }
    );
    assert_eq!(border_for(order_a).unwrap().top.color, NativeColor::RED);
    assert_eq!(
        border_for(order_b).unwrap().top.color,
        NativeColor {
            red: 0,
            green: 0,
            blue: 255,
            alpha: 255
        }
    );
    assert!(!document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && matches!(
                diagnostic.detail.as_str(),
                "border-color"
                    | "border-top-color"
                    | "border-right-color"
                    | "border-bottom-color"
                    | "border-left-color"
            )
    }));

    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(0, 0), Some([0, 0, 255, 255]));
    assert_eq!(surface.pixel(9, 2), Some([0, 128, 0, 255]));
    assert_eq!(surface.pixel(0, 2), Some([0, 0, 0, 255]));
    assert!(!surface.to_png().unwrap().is_empty());
}

#[test]
fn native_border_color_current_color_resolves_after_cascade_and_inheritance() {
    let document = NativeDocument::parse(
        "<style>@layer base { #parent { color:green; } #shorthand { display:block;width:8px;height:6px;color:blue;border:1px solid red;border-color:CURRENTcolor green currentColor black; } #sides { display:block;width:8px;height:6px;color:blue;border:2px dashed red;border-top-color:currentColor;border-right-color:CuRrEnTcOlOr;border-bottom-color:CURRENTCOLOR;border-left-color:currentColor; } #inherited { display:block;width:8px;height:6px;border:1px solid red;border-color:currentColor; } #rollback { display:block;width:8px;height:6px;color:red;border:1px solid red; } #repeat { display:block;width:8px;height:6px;color:red;border:1px solid red; } #same { display:block;width:8px;height:6px;color:green;border:1px solid red;border-color:blue;border-color:currentColor; } #invalid { display:block;width:8px;height:6px;color:blue;border:1px solid red;border-color:green;border-color:invalid; } #complete { display:block;width:8px;height:6px;color:blue;border:1px solid red;border:2px solid currentColor; } #black { display:block;width:8px;height:6px;border:1px solid red;border-color:currentColor; } #inline { display:block;width:8px;height:6px;color:blue;border:1px solid red; } } @layer theme { #rollback { color:blue;border-color:currentColor; } #repeat { color:blue;border-color:currentColor; } #same { border-color:revert-layer; } } @layer top { #rollback { border-color:revert-layer; } #repeat { border-color:currentColor;border-color:revert-layer; } } #inline { color:green;border-color:currentColor; }</style><div id='parent'><button id='shorthand'>Shorthand</button><button id='sides'>Sides</button><button id='inherited'>Inherited</button><button id='rollback'>Rollback</button><button id='repeat'>Repeat</button><button id='same'>Same</button><button id='invalid'>Invalid</button><button id='complete'>Complete</button></div><button id='black'>Black</button><button id='inline'>Inline</button>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 110,
        device_scale_factor_milli: 1000,
    };
    let shorthand = document.resolve_target("id=shorthand").unwrap();
    let sides = document.resolve_target("id=sides").unwrap();
    let inherited = document.resolve_target("id=inherited").unwrap();
    let rollback = document.resolve_target("id=rollback").unwrap();
    let repeat = document.resolve_target("id=repeat").unwrap();
    let same = document.resolve_target("id=same").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let complete = document.resolve_target("id=complete").unwrap();
    let black = document.resolve_target("id=black").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let targets = [
        shorthand, sides, inherited, rollback, repeat, same, invalid, complete, black, inline,
    ];
    let blue = NativeColor {
        red: 0,
        green: 0,
        blue: 255,
        alpha: 255,
    };
    let green = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: 255,
    };

    let layout = document.layout(viewport).unwrap();
    for node_id in targets {
        let rectangle = layout.box_for(node_id).expect("currentColor layout box");
        assert_eq!(
            layout
                .hit_test((rectangle.x + 1).into(), (rectangle.y + 1).into())
                .unwrap(),
            Some(node_id)
        );
    }
    let semantic_nodes = document.semantic_nodes();
    for node_id in targets {
        assert!(
            semantic_nodes
                .iter()
                .any(|node| node.node_id == node_id && !node.hidden),
            "expected currentColor fixture node {node_id:?} to remain visible"
        );
    }

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    let shorthand_border = border_for(shorthand).expect("currentColor shorthand border command");
    assert_eq!(shorthand_border.top.color, blue);
    assert_eq!(shorthand_border.right.color, green);
    assert_eq!(shorthand_border.bottom.color, blue);
    assert_eq!(shorthand_border.left.color, NativeColor::BLACK);
    let sides_border = border_for(sides).expect("currentColor physical border command");
    assert_eq!(sides_border.top.color, blue);
    assert_eq!(sides_border.right.color, blue);
    assert_eq!(sides_border.bottom.color, blue);
    assert_eq!(sides_border.left.color, blue);
    assert_eq!(border_for(inherited).unwrap().top.color, green);
    assert_eq!(border_for(rollback).unwrap().top.color, blue);
    assert_eq!(border_for(repeat).unwrap().top.color, blue);
    assert_eq!(border_for(same).unwrap().top.color, green);
    assert_eq!(border_for(invalid).unwrap().top.color, green);
    assert_eq!(border_for(complete).unwrap().top.width, 2);
    assert_eq!(
        border_for(complete).unwrap().top.style,
        NativeBorderStyle::Solid
    );
    assert_eq!(border_for(complete).unwrap().top.color, blue);
    assert_eq!(border_for(black).unwrap().top.color, NativeColor::BLACK);
    assert_eq!(border_for(inline).unwrap().top.color, green);
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "border-color"
    }));
    assert!(!document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue && diagnostic.detail == "color"
    }));

    let shorthand_box = layout.box_for(shorthand).unwrap();
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(shorthand_box.x, shorthand_box.y),
        Some([0, 0, 255, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
}

#[test]
fn native_border_color_css_wide_keywords_preserve_physical_paint_and_consumers() {
    let document = NativeDocument::parse(
        r#"<style>
            @layer base {
                #parent { display:block;width:32px;height:120px;color:green;border:2px solid red;border-color:red green blue black; }
                .box { display:block;width:8px;height:6px;border-width:1px;border-style:solid; }
                #inherit { color:blue;border-color:inherit; }
                #physical { color:blue;border-top-color:inherit;border-right-color:unset;border-bottom-color:initial;border-left-color:revert; }
                #reset { color:blue;border-color:unset;opacity:0.5; }
                #initial { color:blue;border-color:initial; }
                #revert { color:blue;border-color:revert; }
                #omitted { color:blue; }
                #invalid { color:blue;border-color:inherit;border-color:invalid; }
                #mixed { color:blue;border-color:inherit red; }
                #layered { color:blue;border-color:green; }
                #inline { color:blue;border-color:blue; }
            }
            @layer theme {
                #layered { border-color:inherit; }
            }
            #layered { border-color:revert-layer; }
        </style>
        <div id='parent' role='button'>
            <div id='inherit' class='box' role='button'>Inherit</div>
            <div id='physical' class='box' role='button'>Physical</div>
            <div id='reset' class='box' role='button'>Reset</div>
            <div id='initial' class='box' role='button'>Initial</div>
            <div id='revert' class='box' role='button'>Revert</div>
            <div id='omitted' class='box' role='button'>Omitted</div>
            <div id='invalid' class='box' role='button'>Invalid</div>
            <div id='mixed' class='box' role='button'>Mixed</div>
            <div id='layered' class='box' role='button'>Layered</div>
            <div id='inline' class='box' role='button' style='border-color:inherit'>Inline</div>
        </div>"#,
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 64,
        height: 160,
        device_scale_factor_milli: 1000,
    };
    let parent = document.resolve_target("id=parent").unwrap();
    let inherit = document.resolve_target("id=inherit").unwrap();
    let physical = document.resolve_target("id=physical").unwrap();
    let reset = document.resolve_target("id=reset").unwrap();
    let initial = document.resolve_target("id=initial").unwrap();
    let revert = document.resolve_target("id=revert").unwrap();
    let omitted = document.resolve_target("id=omitted").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let mixed = document.resolve_target("id=mixed").unwrap();
    let layered = document.resolve_target("id=layered").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let targets = [
        parent, inherit, physical, reset, initial, revert, omitted, invalid, mixed, layered, inline,
    ];
    let green = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: u8::MAX,
    };
    let blue = NativeColor {
        red: 0,
        green: 0,
        blue: u8::MAX,
        alpha: u8::MAX,
    };
    let parent_colors = [NativeColor::RED, green, blue, NativeColor::BLACK];

    let layout = document.layout(viewport).unwrap();
    for node_id in targets {
        let rectangle = layout.box_for(node_id).expect("border-color layout box");
        assert_eq!(rectangle.width, if node_id == parent { 36 } else { 10 });
        assert_eq!(rectangle.height, if node_id == parent { 124 } else { 8 });
        assert_eq!(
            layout
                .hit_test((rectangle.x + 1).into(), (rectangle.y + 1).into())
                .unwrap(),
            Some(node_id)
        );
    }

    let semantic_nodes = document.semantic_nodes();
    for node_id in targets {
        assert!(
            semantic_nodes
                .iter()
                .any(|node| node.node_id == node_id && !node.hidden),
            "expected border-color fixture node {node_id:?} to remain visible"
        );
    }

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    let parent_border = border_for(parent).expect("parent border command");
    assert_eq!(
        [
            parent_border.top.color,
            parent_border.right.color,
            parent_border.bottom.color,
            parent_border.left.color,
        ],
        parent_colors
    );
    assert_eq!(border_for(inherit).unwrap().top.color, NativeColor::RED);
    assert_eq!(border_for(inherit).unwrap().right.color, green);
    assert_eq!(border_for(inherit).unwrap().bottom.color, blue);
    assert_eq!(border_for(inherit).unwrap().left.color, NativeColor::BLACK);
    let physical_border = border_for(physical).expect("physical border command");
    assert_eq!(physical_border.top.color, NativeColor::RED);
    assert_eq!(physical_border.right.color, blue);
    assert_eq!(physical_border.bottom.color, blue);
    assert_eq!(physical_border.left.color, blue);
    for node_id in [reset, initial, revert] {
        let borders = border_for(node_id).expect("CSS-wide reset border command");
        assert_eq!(
            [
                borders.top.color,
                borders.right.color,
                borders.bottom.color,
                borders.left.color
            ],
            [blue; 4]
        );
        assert_eq!(borders.top.width, 1);
        assert_eq!(borders.top.style, NativeBorderStyle::Solid);
    }
    assert_eq!(
        [
            border_for(omitted).unwrap().top.color,
            border_for(omitted).unwrap().right.color,
            border_for(omitted).unwrap().bottom.color,
            border_for(omitted).unwrap().left.color,
        ],
        [NativeColor::BLACK; 4]
    );
    assert_eq!(border_for(invalid).unwrap().top.color, NativeColor::RED);
    assert_eq!(border_for(mixed).unwrap().top.color, NativeColor::BLACK);
    assert_eq!(border_for(layered).unwrap().top.color, NativeColor::RED);
    assert_eq!(border_for(inline).unwrap().top.color, NativeColor::RED);
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::BeginOpacityGroup {
                node_id,
                opacity: 128
            } if *node_id == reset
        )
    }));
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "border-color"
    }));
    assert!(!document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && matches!(
                diagnostic.detail.as_str(),
                "border-top-color"
                    | "border-right-color"
                    | "border-bottom-color"
                    | "border-left-color"
            )
    }));

    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(
            layout.box_for(parent).unwrap().x,
            layout.box_for(parent).unwrap().y
        ),
        Some([255, 0, 0, 255])
    );
    assert_eq!(
        surface.pixel(
            layout.box_for(reset).unwrap().x,
            layout.box_for(reset).unwrap().y
        ),
        Some([127, 127, 255, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
}

#[test]
fn native_physical_border_color_important_priority_reaches_border_artifacts() {
    let document = NativeDocument::parse(
        r#"<style>
            .box { display:block;width:16px;height:8px;border:2px solid black; }
            @layer base {
                #early { border-color:red !important; }
                #rollback { border-color:red !important; }
                #rollback { border-color:revert-layer !important; }
                #normal { border-color:red; }
                #mixed { border-color:red !important; }
                #sides { border-color:red !important;border-top-color:blue !important;border-right-color:green !important; }
                #sides { border-bottom-color:blue;border-left-color:green; }
                #invalid { border-color:red !important;border-color:invalid !important; }
            }
            @layer theme {
                #early { border-color:blue !important; }
                #rollback { border-color:green !important; }
                #normal { border-color:blue; }
                #sides { border-color:green !important; }
            }
            #early { border-color:green !important; }
            #normal { border-color:green; }
            #mixed { border-color:green; }
            #sides { border-color:green !important; }
            #inline { border-color:red !important; }
        </style>
        <div id='early' class='box' role='button'>Early</div>
        <div id='rollback' class='box' role='button'>Rollback</div>
        <div id='normal' class='box' role='button'>Normal</div>
        <div id='mixed' class='box' role='button'>Mixed</div>
        <div id='sides' class='box' role='button'>Sides</div>
        <div id='invalid' class='box' role='button'>Invalid</div>
        <div id='inline' class='box' role='button' style='border-color:green !important'>Inline</div>"#,
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 100,
        device_scale_factor_milli: 1000,
    };
    let early = document.resolve_target("id=early").unwrap();
    let rollback = document.resolve_target("id=rollback").unwrap();
    let normal = document.resolve_target("id=normal").unwrap();
    let mixed = document.resolve_target("id=mixed").unwrap();
    let sides = document.resolve_target("id=sides").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let targets = [early, rollback, normal, mixed, sides, invalid, inline];
    let blue = NativeColor {
        red: 0,
        green: 0,
        blue: u8::MAX,
        alpha: u8::MAX,
    };
    let green = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: u8::MAX,
    };
    let layout = document.layout(viewport).unwrap();
    for node_id in targets {
        let rectangle = layout.box_for(node_id).expect("border-color layout box");
        assert_eq!(rectangle.width, 20);
        assert_eq!(rectangle.height, 12);
        assert_eq!(
            layout
                .hit_test((rectangle.x + 3).into(), (rectangle.y + 3).into())
                .unwrap(),
            Some(node_id)
        );
    }

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    for (node_id, expected) in [
        (early, [NativeColor::RED; 4]),
        (rollback, [green; 4]),
        (normal, [green; 4]),
        (mixed, [NativeColor::RED; 4]),
        (sides, [blue, green, NativeColor::RED, NativeColor::RED]),
        (invalid, [NativeColor::RED; 4]),
        (inline, [green; 4]),
    ] {
        let borders = border_for(node_id).expect("border-color command");
        assert_eq!(
            [
                borders.top.color,
                borders.right.color,
                borders.bottom.color,
                borders.left.color,
            ],
            expected,
            "border colors for {node_id:?}"
        );
        assert_eq!(borders.top.width, 2);
        assert_eq!(borders.top.style, NativeBorderStyle::Solid);
    }
    let semantic_ids = document
        .semantic_nodes()
        .into_iter()
        .map(|node| node.node_id)
        .collect::<Vec<_>>();
    for pair in targets.windows(2) {
        assert!(
            semantic_ids.iter().position(|id| *id == pair[0])
                < semantic_ids.iter().position(|id| *id == pair[1]),
            "semantic/source order lost for {pair:?}"
        );
    }
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "border-color"
    }));
    let early_box = layout.box_for(early).unwrap();
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(early_box.x + 10, early_box.y),
        Some([255, 0, 0, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
}

#[test]
fn native_physical_border_width_important_priority_reaches_border_artifacts() {
    let document = NativeDocument::parse(
        r#"<style>
            .box { display:block;width:16px;height:8px;border:2px solid black; }
            @layer base {
                #early { border-width:1px !important; }
                #rollback { border-width:1px !important; }
                #rollback { border-width:revert-layer !important; }
                #normal { border-width:1px; }
                #mixed { border-top-width:1px !important; }
                #sides { border-width:1px !important;border-top-width:2px !important;border-right-width:3px !important; }
                #invalid { border-width:1px !important;border-width:invalid !important; }
            }
            @layer theme {
                #early { border-width:2px !important; }
                #rollback { border-width:3px !important; }
                #normal { border-width:2px; }
                #sides { border-width:4px !important; }
            }
            #early { border-width:3px !important; }
            #normal { border-width:3px; }
            #mixed { border-width:4px; }
            #sides { border-width:5px !important; }
            #invalid { border-width:5px; }
        </style>
        <div id='early' class='box' role='button'>Early</div>
        <div id='rollback' class='box' role='button'>Rollback</div>
        <div id='normal' class='box' role='button'>Normal</div>
        <div id='mixed' class='box' role='button'>Mixed</div>
        <div id='sides' class='box' role='button'>Sides</div>
        <div id='invalid' class='box' role='button'>Invalid</div>
        <div id='inline' class='box' role='button' style='border-width:4px !important'>Inline</div>
        <div id='width-only' style='display:block;width:8px;height:6px;border-width:3px !important'>Only</div>"#,
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 160,
        device_scale_factor_milli: 1000,
    };
    let early = document.resolve_target("id=early").unwrap();
    let rollback = document.resolve_target("id=rollback").unwrap();
    let normal = document.resolve_target("id=normal").unwrap();
    let mixed = document.resolve_target("id=mixed").unwrap();
    let sides = document.resolve_target("id=sides").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let width_only = document.resolve_target("id=width-only").unwrap();
    let targets = [early, rollback, normal, mixed, sides, invalid, inline];
    let layout = document.layout(viewport).unwrap();
    for (node_id, (expected_width, expected_height)) in [
        (early, (18, 10)),
        (rollback, (22, 14)),
        (normal, (22, 14)),
        (mixed, (24, 13)),
        (sides, (20, 11)),
        (invalid, (18, 10)),
        (inline, (24, 16)),
    ] {
        let rectangle = layout.box_for(node_id).expect("border-width layout box");
        assert_eq!(rectangle.width, expected_width);
        assert_eq!(rectangle.height, expected_height);
        assert_eq!(
            layout
                .hit_test((rectangle.x + 3).into(), (rectangle.y + 3).into())
                .unwrap(),
            Some(node_id)
        );
    }
    let width_only_box = layout.box_for(width_only).expect("width-only layout box");
    assert_eq!(width_only_box.width, 8);
    assert_eq!(width_only_box.height, 6);

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    for (node_id, expected_widths) in [
        (early, [1, 1, 1, 1]),
        (rollback, [3, 3, 3, 3]),
        (normal, [3, 3, 3, 3]),
        (mixed, [1, 4, 4, 4]),
        (sides, [2, 3, 1, 1]),
        (invalid, [1, 1, 1, 1]),
        (inline, [4, 4, 4, 4]),
    ] {
        let borders = border_for(node_id).expect("border-width command");
        assert_eq!(
            [
                borders.top.width,
                borders.right.width,
                borders.bottom.width,
                borders.left.width,
            ],
            expected_widths,
            "border widths for {node_id:?}"
        );
        assert_eq!(
            [
                borders.top.color,
                borders.right.color,
                borders.bottom.color,
                borders.left.color,
            ],
            [NativeColor::BLACK; 4]
        );
        assert_eq!(borders.top.style, NativeBorderStyle::Solid);
    }
    assert!(border_for(width_only).is_none());
    let semantic_ids = document
        .semantic_nodes()
        .into_iter()
        .map(|node| node.node_id)
        .collect::<Vec<_>>();
    for pair in targets.windows(2) {
        assert!(
            semantic_ids.iter().position(|id| *id == pair[0])
                < semantic_ids.iter().position(|id| *id == pair[1]),
            "semantic/source order lost for {pair:?}"
        );
    }
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "border-width"
    }));
    let early_box = layout.box_for(early).unwrap();
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(early_box.x + 10, early_box.y),
        Some([0, 0, 0, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
}

#[test]
fn native_physical_border_style_important_priority_reaches_border_artifacts() {
    let document = NativeDocument::parse(
        r#"<style>
            .box { display:block;width:16px;height:8px;border:2px solid black; }
            @layer base {
                #early { border-style:solid !important; }
                #rollback { border-style:dashed !important; }
                #rollback { border-style:revert-layer !important; }
                #normal { border-style:dotted; }
                #mixed { border-top-style:hidden !important; }
                #sides { border-style:solid !important;border-top-style:none !important;border-right-style:hidden !important; }
                #invalid { border-style:double !important;border-style:invalid !important; }
            }
            @layer theme {
                #early { border-style:dashed !important; }
                #rollback { border-style:groove !important; }
                #normal { border-style:double; }
                #sides { border-style:ridge !important; }
            }
            #early { border-style:dotted !important; }
            #normal { border-style:outset; }
            #mixed { border-style:double; }
            #sides { border-style:inset !important; }
            #invalid { border-style:dashed; }
        </style>
        <div id='early' class='box' role='button'>Early</div>
        <div id='rollback' class='box' role='button'>Rollback</div>
        <div id='normal' class='box' role='button'>Normal</div>
        <div id='mixed' class='box' role='button'>Mixed</div>
        <div id='sides' class='box' role='button'>Sides</div>
        <div id='invalid' class='box' role='button'>Invalid</div>
        <div id='inline' class='box' role='button' style='border-style:hidden !important'>Inline</div>
        <div id='style-only' style='display:block;width:8px;height:6px;border-style:solid !important'>Only</div>"#,
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 160,
        device_scale_factor_milli: 1000,
    };
    let early = document.resolve_target("id=early").unwrap();
    let rollback = document.resolve_target("id=rollback").unwrap();
    let normal = document.resolve_target("id=normal").unwrap();
    let mixed = document.resolve_target("id=mixed").unwrap();
    let sides = document.resolve_target("id=sides").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let style_only = document.resolve_target("id=style-only").unwrap();
    let targets = [early, rollback, normal, mixed, sides, invalid, inline];
    let layout = document.layout(viewport).unwrap();
    for (node_id, (expected_width, expected_height)) in [
        (early, (20, 12)),
        (rollback, (20, 12)),
        (normal, (20, 12)),
        (mixed, (20, 10)),
        (sides, (18, 10)),
        (invalid, (20, 12)),
        (inline, (16, 8)),
    ] {
        let rectangle = layout.box_for(node_id).expect("border-style layout box");
        assert_eq!(rectangle.width, expected_width);
        assert_eq!(rectangle.height, expected_height);
        assert_eq!(
            layout
                .hit_test((rectangle.x + 3).into(), (rectangle.y + 3).into())
                .unwrap(),
            Some(node_id)
        );
    }
    let style_only_box = layout.box_for(style_only).expect("style-only layout box");
    assert_eq!((style_only_box.width, style_only_box.height), (8, 6));

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    for (node_id, expected_style) in [
        (early, NativeBorderStyle::Solid),
        (rollback, NativeBorderStyle::Groove),
        (normal, NativeBorderStyle::Outset),
        (invalid, NativeBorderStyle::Double),
    ] {
        let borders = border_for(node_id).expect("border-style command");
        assert_eq!(
            [
                borders.top.style,
                borders.right.style,
                borders.bottom.style,
                borders.left.style,
            ],
            [expected_style; 4],
            "border styles for {node_id:?}"
        );
        assert_eq!(
            [
                borders.top.width,
                borders.right.width,
                borders.bottom.width,
                borders.left.width,
            ],
            [2; 4]
        );
        assert_eq!(
            [
                borders.top.color,
                borders.right.color,
                borders.bottom.color,
                borders.left.color,
            ],
            [NativeColor::BLACK; 4]
        );
    }
    let mixed_border = border_for(mixed).expect("mixed border-style command");
    assert_eq!(mixed_border.top.width, 0);
    assert_eq!(mixed_border.top.style, NativeBorderStyle::Solid);
    assert_eq!(mixed_border.right.style, NativeBorderStyle::Double);
    assert_eq!(mixed_border.bottom.style, NativeBorderStyle::Double);
    assert_eq!(mixed_border.left.style, NativeBorderStyle::Double);
    assert_eq!(mixed_border.right.width, 2);
    let sides_border = border_for(sides).expect("side border-style command");
    assert_eq!(sides_border.top.width, 0);
    assert_eq!(sides_border.right.width, 0);
    assert_eq!(sides_border.bottom.style, NativeBorderStyle::Solid);
    assert_eq!(sides_border.left.style, NativeBorderStyle::Solid);
    assert!(border_for(inline).is_none());
    assert!(border_for(style_only).is_none());

    let semantic_ids = document
        .semantic_nodes()
        .into_iter()
        .map(|node| node.node_id)
        .collect::<Vec<_>>();
    for pair in targets.windows(2) {
        assert!(
            semantic_ids.iter().position(|id| *id == pair[0])
                < semantic_ids.iter().position(|id| *id == pair[1]),
            "semantic/source order lost for {pair:?}"
        );
    }
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "border-style"
    }));
    let early_box = layout.box_for(early).unwrap();
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(early_box.x + 10, early_box.y),
        Some([0, 0, 0, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
}

#[test]
fn native_physical_border_shorthand_important_priority_reaches_border_artifacts() {
    let document = NativeDocument::parse(
        r#"<style>
            .box { display:block;width:16px;height:8px;border:2px solid black; }
            @layer base {
                #early { border:1px solid red !important; }
                #rollback { border:1px solid blue !important; }
                #rollback { border:revert-layer !important; }
                #normal { border:1px solid red; }
                #mixed { border-top:1px dashed blue !important; }
                #sides { border:1px solid red !important;border-top:2px dashed green !important;border-right:3px dotted blue !important; }
                #invalid { border:1px solid red !important;border:invalid !important; }
                #none { border:2px solid red !important;border-top:none !important; }
                #hidden { border:2px solid red !important;border-right:hidden !important; }
            }
            @layer theme {
                #early { border:2px dashed blue !important; }
                #rollback { border:3px groove green !important; }
                #normal { border:2px dashed blue; }
                #sides { border:4px groove green !important; }
            }
            #early { border:3px dotted green !important; }
            #normal { border:3px double green; }
            #mixed { border:4px double black; }
            #sides { border:5px ridge red !important; }
            #invalid { border:5px outset green; }
            #none { border-top:4px solid blue; }
            #hidden { border-right:4px solid blue; }
        </style>
        <div id='early' class='box' role='button'>Early</div>
        <div id='rollback' class='box' role='button'>Rollback</div>
        <div id='normal' class='box' role='button'>Normal</div>
        <div id='mixed' class='box' role='button'>Mixed</div>
        <div id='sides' class='box' role='button'>Sides</div>
        <div id='invalid' class='box' role='button'>Invalid</div>
        <div id='none' class='box' role='button'>None</div>
        <div id='hidden' class='box' role='button'>Hidden</div>
        <div id='inline' class='box' role='button' style='border:6px groove blue !important'>Inline</div>"#,
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 200,
        device_scale_factor_milli: 1000,
    };
    let early = document.resolve_target("id=early").unwrap();
    let rollback = document.resolve_target("id=rollback").unwrap();
    let normal = document.resolve_target("id=normal").unwrap();
    let mixed = document.resolve_target("id=mixed").unwrap();
    let sides = document.resolve_target("id=sides").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let none = document.resolve_target("id=none").unwrap();
    let hidden = document.resolve_target("id=hidden").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let targets = [
        early, rollback, normal, mixed, sides, invalid, none, hidden, inline,
    ];
    let blue = NativeColor {
        red: 0,
        green: 0,
        blue: u8::MAX,
        alpha: u8::MAX,
    };
    let green = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: u8::MAX,
    };
    let layout = document.layout(viewport).unwrap();
    for (node_id, (expected_width, expected_height)) in [
        (early, (18, 10)),
        (rollback, (22, 14)),
        (normal, (22, 14)),
        (mixed, (24, 13)),
        (sides, (20, 11)),
        (invalid, (18, 10)),
        (none, (20, 10)),
        (hidden, (18, 12)),
        (inline, (28, 20)),
    ] {
        let rectangle = layout
            .box_for(node_id)
            .expect("border-shorthand layout box");
        assert_eq!(rectangle.width, expected_width);
        assert_eq!(rectangle.height, expected_height);
        assert_eq!(
            layout
                .hit_test((rectangle.x + 3).into(), (rectangle.y + 3).into())
                .unwrap(),
            Some(node_id)
        );
    }

    let list = document.display_list(viewport).unwrap();
    let border_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::BorderRect {
                node_id: command_node_id,
                borders,
                ..
            } if *command_node_id == node_id => Some(*borders),
            _ => None,
        })
    };
    let early_border = border_for(early).expect("early border-shorthand command");
    assert_eq!(
        [
            early_border.top.width,
            early_border.right.width,
            early_border.bottom.width,
            early_border.left.width,
        ],
        [1; 4]
    );
    assert_eq!(
        [
            early_border.top.style,
            early_border.right.style,
            early_border.bottom.style,
            early_border.left.style,
        ],
        [NativeBorderStyle::Solid; 4]
    );
    assert_eq!(
        [
            early_border.top.color,
            early_border.right.color,
            early_border.bottom.color,
            early_border.left.color,
        ],
        [NativeColor::RED; 4]
    );

    let rollback_border = border_for(rollback).expect("rollback border-shorthand command");
    assert_eq!(rollback_border.top.width, 3);
    assert_eq!(rollback_border.top.style, NativeBorderStyle::Groove);
    assert_eq!(rollback_border.top.color, green);

    let mixed_border = border_for(mixed).expect("mixed border-shorthand command");
    assert_eq!(mixed_border.top.width, 1);
    assert_eq!(mixed_border.top.style, NativeBorderStyle::Dashed);
    assert_eq!(mixed_border.top.color, blue);
    assert_eq!(mixed_border.right.width, 4);
    assert_eq!(mixed_border.right.style, NativeBorderStyle::Double);
    assert_eq!(mixed_border.right.color, NativeColor::BLACK);

    let sides_border = border_for(sides).expect("side border-shorthand command");
    assert_eq!(
        [
            sides_border.top.width,
            sides_border.right.width,
            sides_border.bottom.width,
            sides_border.left.width,
        ],
        [2, 3, 1, 1]
    );
    assert_eq!(sides_border.top.style, NativeBorderStyle::Dashed);
    assert_eq!(sides_border.right.style, NativeBorderStyle::Dotted);
    assert_eq!(sides_border.bottom.style, NativeBorderStyle::Solid);
    assert_eq!(sides_border.left.style, NativeBorderStyle::Solid);
    assert_eq!(sides_border.top.color, green);
    assert_eq!(sides_border.right.color, blue);
    assert_eq!(sides_border.bottom.color, NativeColor::RED);
    assert_eq!(sides_border.left.color, NativeColor::RED);

    let invalid_border = border_for(invalid).expect("invalid border-shorthand command");
    assert_eq!(invalid_border.top.width, 1);
    assert_eq!(invalid_border.top.style, NativeBorderStyle::Solid);
    assert_eq!(invalid_border.top.color, NativeColor::RED);

    let none_border = border_for(none).expect("none border-shorthand command");
    assert_eq!(none_border.top.width, 0);
    assert_eq!(none_border.top.style, NativeBorderStyle::Solid);
    assert_eq!(none_border.bottom.width, 2);
    assert_eq!(none_border.bottom.style, NativeBorderStyle::Solid);
    let hidden_border = border_for(hidden).expect("hidden border-shorthand command");
    assert_eq!(hidden_border.right.width, 0);
    assert_eq!(hidden_border.right.style, NativeBorderStyle::Solid);
    assert_eq!(hidden_border.left.width, 2);
    assert_eq!(hidden_border.left.style, NativeBorderStyle::Solid);

    let inline_border = border_for(inline).expect("inline border-shorthand command");
    assert_eq!(inline_border.top.width, 6);
    assert_eq!(inline_border.top.style, NativeBorderStyle::Groove);
    assert_eq!(inline_border.top.color, blue);

    let semantic_ids = document
        .semantic_nodes()
        .into_iter()
        .map(|node| node.node_id)
        .collect::<Vec<_>>();
    for pair in targets.windows(2) {
        assert!(
            semantic_ids.iter().position(|id| *id == pair[0])
                < semantic_ids.iter().position(|id| *id == pair[1]),
            "semantic/source order lost for {pair:?}"
        );
    }
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "border"
    }));
    let early_box = layout.box_for(early).unwrap();
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(early_box.x + 8, early_box.y),
        Some([255, 0, 0, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
}

