#[test]
fn native_text_align_last_resolves_final_lines_through_shared_artifacts() {
    let document = NativeDocument::parse(
        "<style>.block { display:block; width:45px; text-align:justify; } #center { text-align-last:center; } #right { text-align-last:right; } #start-rtl { direction:rtl; text-align-last:start; } #end-rtl { direction:rtl; text-align-last:end; } #auto { text-align-last:auto; } #hard { text-align-last:right; }</style><div id='center' class='block'>A B C D</div><div id='right' class='block'>A B C D</div><div id='start-rtl' class='block'>A B C D</div><div id='end-rtl' class='block'>A B C D</div><div id='auto' class='block'>A B C D</div><div id='hard' class='block'>A B C<br>D</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 45,
        height: 280,
        device_scale_factor_milli: 1000,
    };
    let center = document.resolve_target("id=center").unwrap();
    let right = document.resolve_target("id=right").unwrap();
    let start_rtl = document.resolve_target("id=start-rtl").unwrap();
    let end_rtl = document.resolve_target("id=end-rtl").unwrap();
    let auto = document.resolve_target("id=auto").unwrap();
    let hard = document.resolve_target("id=hard").unwrap();
    let layout = document.layout(viewport).unwrap();

    let final_origin = |node_id| {
        layout
            .text_runs
            .iter()
            .find(|run| run.node_id == node_id && run.text == "D" && run.origin.y > 0)
            .map(|run| run.origin)
            .unwrap()
    };
    assert_eq!(final_origin(center), NativePoint { x: 18, y: 20 });
    assert_eq!(final_origin(right), NativePoint { x: 37, y: 60 });
    assert_eq!(final_origin(start_rtl), NativePoint { x: 37, y: 100 });
    assert_eq!(final_origin(end_rtl), NativePoint { x: 0, y: 140 });
    assert_eq!(final_origin(auto), NativePoint { x: 0, y: 180 });
    assert_eq!(final_origin(hard), NativePoint { x: 37, y: 220 });

    let hard_runs = layout
        .text_runs
        .iter()
        .filter(|run| run.node_id == hard)
        .collect::<Vec<_>>();
    assert!(hard_runs.iter().all(|run| run.justify_spacing == 0));
    assert_eq!(layout.box_for(center).unwrap().height, 40);

    let display_list = document.display_list(viewport).unwrap();
    assert!(display_list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::TextRun {
                node_id,
                origin: NativePoint { x: 18, y: 20 },
                text,
                ..
            } if *node_id == center && text == "D"
        )
    }));
    let surface = display_list.rasterize().unwrap();
    assert_eq!(surface.pixel(18, 20), Some([0, 0, 0, 255]));
}

#[test]
fn native_text_align_last_justifies_final_lines_without_changing_other_paths() {
    let document = NativeDocument::parse(
        "<style>.block { display:block; width:45px; text-align-last:justify; } #tight { width:40px; } #pre { white-space:pre; } #pre-wrap { white-space:pre-wrap; } #break { word-break:break-all; } #spacing { word-spacing:2px; }</style><div id='target' class='block'>A B C</div><div id='tight' class='block'>A B C</div><div id='hard' class='block'>A B<br>C D</div><div id='pre' class='block'>A B C</div><div id='pre-wrap' class='block'>A B C</div><div id='break' class='block'>A B C</div><div id='spacing' class='block'>A B C</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 45,
        height: 240,
        device_scale_factor_milli: 1000,
    };
    let target = document.resolve_target("id=target").unwrap();
    let tight = document.resolve_target("id=tight").unwrap();
    let hard = document.resolve_target("id=hard").unwrap();
    let pre = document.resolve_target("id=pre").unwrap();
    let pre_wrap = document.resolve_target("id=pre-wrap").unwrap();
    let break_all = document.resolve_target("id=break").unwrap();
    let spacing = document.resolve_target("id=spacing").unwrap();
    let layout = document.layout(viewport).unwrap();
    let runs_for = |node_id| {
        layout
            .text_runs
            .iter()
            .filter(|run| run.node_id == node_id)
            .map(|run| (run.origin, run.text.as_str(), run.justify_spacing))
            .collect::<Vec<_>>()
    };

    assert_eq!(
        runs_for(target),
        vec![
            (NativePoint { x: 0, y: 0 }, "A", 0),
            (NativePoint { x: 8, y: 0 }, " B", 3),
            (NativePoint { x: 27, y: 0 }, " C", 2),
        ]
    );
    assert_eq!(
        runs_for(tight),
        vec![
            (NativePoint { x: 0, y: 20 }, "A", 0),
            (NativePoint { x: 8, y: 20 }, " B", 0),
            (NativePoint { x: 24, y: 20 }, " C", 0),
        ]
    );
    assert_eq!(
        runs_for(hard),
        vec![
            (NativePoint { x: 0, y: 40 }, "A", 0),
            (NativePoint { x: 8, y: 40 }, " B", 0),
            (NativePoint { x: 0, y: 60 }, "C", 0),
            (NativePoint { x: 8, y: 60 }, " D", 21),
        ]
    );
    assert_eq!(
        runs_for(pre),
        vec![(NativePoint { x: 0, y: 80 }, "A B C", 0)]
    );
    assert_eq!(
        runs_for(pre_wrap),
        vec![(NativePoint { x: 0, y: 100 }, "A B C", 0)]
    );
    assert_eq!(
        runs_for(break_all),
        vec![
            (NativePoint { x: 0, y: 120 }, "A", 0),
            (NativePoint { x: 8, y: 120 }, " B", 0),
            (NativePoint { x: 24, y: 120 }, " C", 0),
        ]
    );
    assert_eq!(
        runs_for(spacing),
        vec![
            (NativePoint { x: 0, y: 140 }, "A", 0),
            (NativePoint { x: 8, y: 140 }, " B", 1),
            (NativePoint { x: 27, y: 140 }, " C", 0),
        ]
    );
    assert_eq!(layout.box_for(target).unwrap().height, 20);

    let display_list = document.display_list(viewport).unwrap();
    let target_commands = display_list
        .commands
        .iter()
        .filter_map(|command| match command {
            NativeDisplayCommand::TextRun {
                node_id,
                origin,
                text,
                justify_spacing,
                ..
            } if *node_id == target => Some((*origin, text.as_str(), *justify_spacing)),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(target_commands, runs_for(target));
    let surface = display_list.rasterize().unwrap();
    assert_eq!(surface.pixel(1, 0), Some([0, 0, 0, 255]));
}

#[test]
fn native_text_justify_controls_both_justification_flushes() {
    let document = NativeDocument::parse(
        "<style>.soft { display:block; width:45px; text-align:justify; } #none-soft { text-justify:none; } #inter-word-soft { text-justify:inter-word; } .final { display:block; width:45px; text-align:left; text-align-last:justify; } #none-final { text-justify:none; } #alone { display:block; width:45px; text-align:left; text-justify:inter-word; } #spacing-none { display:block; width:45px; text-align:justify; word-spacing:2px; text-justify:none; }</style><div id='auto-soft' class='soft'>A B C D</div><div id='none-soft' class='soft'>A B C D</div><div id='inter-word-soft' class='soft'>A B C D</div><div id='auto-final' class='final'>A B C</div><div id='none-final' class='final'>A B C</div><div id='alone' >A B C</div><div id='spacing-none'>A B C</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 45,
        height: 180,
        device_scale_factor_milli: 1000,
    };
    let auto_soft = document.resolve_target("id=auto-soft").unwrap();
    let none_soft = document.resolve_target("id=none-soft").unwrap();
    let inter_word_soft = document.resolve_target("id=inter-word-soft").unwrap();
    let auto_final = document.resolve_target("id=auto-final").unwrap();
    let none_final = document.resolve_target("id=none-final").unwrap();
    let alone = document.resolve_target("id=alone").unwrap();
    let spacing_none = document.resolve_target("id=spacing-none").unwrap();
    let layout = document.layout(viewport).unwrap();
    let runs_for = |node_id| {
        layout
            .text_runs
            .iter()
            .filter(|run| run.node_id == node_id)
            .map(|run| (run.origin, run.text.as_str(), run.justify_spacing))
            .collect::<Vec<_>>()
    };
    let first_line = |y: u32, spacing: [u32; 2]| {
        vec![
            (NativePoint { x: 0, y }, "A", 0),
            (NativePoint { x: 8, y }, " B", spacing[0]),
            (NativePoint { x: 27, y }, " C", spacing[1]),
            (NativePoint { x: 0, y: y + 20 }, "D", 0),
        ]
    };

    assert_eq!(runs_for(auto_soft), first_line(0, [3, 2]));
    assert_eq!(
        runs_for(none_soft),
        vec![
            (NativePoint { x: 0, y: 40 }, "A", 0),
            (NativePoint { x: 8, y: 40 }, " B", 0),
            (NativePoint { x: 24, y: 40 }, " C", 0),
            (NativePoint { x: 0, y: 60 }, "D", 0),
        ]
    );
    assert_eq!(runs_for(inter_word_soft), first_line(80, [3, 2]));
    assert_eq!(
        runs_for(auto_final),
        first_line(120, [3, 2])
            .into_iter()
            .take(3)
            .collect::<Vec<_>>()
    );
    assert_eq!(
        runs_for(none_final),
        vec![
            (NativePoint { x: 0, y: 140 }, "A", 0),
            (NativePoint { x: 8, y: 140 }, " B", 0),
            (NativePoint { x: 24, y: 140 }, " C", 0),
        ]
    );
    assert_eq!(
        runs_for(alone),
        vec![
            (NativePoint { x: 0, y: 160 }, "A", 0),
            (NativePoint { x: 8, y: 160 }, " B", 0),
            (NativePoint { x: 24, y: 160 }, " C", 0),
        ]
    );
    assert_eq!(
        runs_for(spacing_none),
        vec![
            (NativePoint { x: 0, y: 180 }, "A", 0),
            (NativePoint { x: 8, y: 180 }, " B", 0),
            (NativePoint { x: 26, y: 180 }, " C", 0),
        ]
    );

    let display_list = document.display_list(viewport).unwrap();
    let none_commands = display_list
        .commands
        .iter()
        .filter_map(|command| match command {
            NativeDisplayCommand::TextRun {
                node_id,
                origin,
                text,
                justify_spacing,
                ..
            } if *node_id == none_final => Some((*origin, text.as_str(), *justify_spacing)),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(none_commands, runs_for(none_final));

    let surface = display_list.rasterize().unwrap();
    assert_eq!(surface.pixel(1, 0), Some([0, 0, 0, 255]));
}

#[test]
fn native_text_decoration_inherits_through_contents_and_reaches_raster() {
    let document = NativeDocument::parse(
        "<style>#parent { display:block; width:32px; text-decoration:underline overline; color:rgba(0, 128, 0, 50%); } #clear { text-decoration:none; } #contents { display:contents; }</style><div id='parent'>A<span id='clear'>B</span><span id='contents'><span id='nested'>C</span></span></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 40,
        height: 20,
        device_scale_factor_milli: 1000,
    };
    let parent = document.resolve_target("id=parent").unwrap();
    let clear = document.resolve_target("id=clear").unwrap();
    let contents = document.resolve_target("id=contents").unwrap();
    let nested = document.resolve_target("id=nested").unwrap();
    let list = document.display_list(viewport).unwrap();
    let text_runs = list
        .commands
        .iter()
        .filter_map(|command| match command {
            NativeDisplayCommand::TextRun {
                node_id,
                origin,
                text,
                color,
                underline,
                overline,
                line_through,
                ..
            } => Some((
                *node_id,
                *origin,
                text.as_str(),
                *color,
                *underline,
                *overline,
                *line_through,
            )),
            _ => None,
        })
        .collect::<Vec<_>>();
    let expected_color = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: 128,
    };
    assert!(text_runs.iter().any(
        |(node_id, origin, text, color, underline, overline, line_through)| {
            *node_id == parent
                && *origin == NativePoint { x: 0, y: 0 }
                && *text == "A"
                && *color == expected_color
                && *underline
                && *overline
                && !*line_through
        }
    ));
    assert!(text_runs.iter().any(
        |(node_id, _, text, color, underline, overline, line_through)| {
            *node_id == clear
                && *text == "B"
                && *color == expected_color
                && !*underline
                && !*overline
                && !*line_through
        }
    ));
    assert!(
        !text_runs
            .iter()
            .any(|(node_id, _, _, _, _, _, _)| *node_id == contents)
    );
    assert!(text_runs.iter().any(
        |(node_id, _, text, color, underline, overline, line_through)| {
            *node_id == nested
                && *text == "C"
                && *color == expected_color
                && *underline
                && *overline
                && !*line_through
        }
    ));

    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(0, 7), Some([127, 191, 127, 255]));
    assert_eq!(surface.pixel(8, 7), Some([255, 255, 255, 255]));
    assert_eq!(surface.pixel(16, 7), Some([127, 191, 127, 255]));
}

#[test]
fn native_text_decoration_line_styles_share_layout_and_artifacts() {
    let document = NativeDocument::parse(
        "<style>.line { display:block; width:24px; height:20px; line-height:20px; color:black; } #plain { text-decoration:none; } #over { text-decoration:overline; } #through { text-decoration:line-through; } #under { text-decoration:underline; }</style><div id='plain' class='line'>A</div><div id='over' class='line'>A</div><div id='through' class='line'>A</div><div id='under' class='line'>A</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 80,
        device_scale_factor_milli: 1000,
    };
    let plain = document.resolve_target("id=plain").unwrap();
    let over = document.resolve_target("id=over").unwrap();
    let through = document.resolve_target("id=through").unwrap();
    let under = document.resolve_target("id=under").unwrap();
    let layout = document.layout(viewport).unwrap();
    let runs_for = |node_id| {
        layout
            .text_runs
            .iter()
            .filter(|run| run.node_id == node_id)
            .map(|run| {
                (
                    run.origin,
                    run.text.as_str(),
                    run.truncated,
                    run.justify_spacing,
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        runs_for(plain),
        vec![(NativePoint { x: 0, y: 0 }, "A", false, 0)]
    );
    assert_eq!(
        runs_for(over),
        vec![(NativePoint { x: 0, y: 20 }, "A", false, 0)]
    );
    assert_eq!(
        runs_for(through),
        vec![(NativePoint { x: 0, y: 40 }, "A", false, 0)]
    );
    assert_eq!(
        runs_for(under),
        vec![(NativePoint { x: 0, y: 60 }, "A", false, 0)]
    );

    let list = document.display_list(viewport).unwrap();
    let decoration_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::TextRun {
                node_id: command_node_id,
                underline,
                overline,
                line_through,
                ..
            } if *command_node_id == node_id => Some((*underline, *overline, *line_through)),
            _ => None,
        })
    };
    assert_eq!(decoration_for(plain), Some((false, false, false)));
    assert_eq!(decoration_for(over), Some((false, true, false)));
    assert_eq!(decoration_for(through), Some((false, false, true)));
    assert_eq!(decoration_for(under), Some((true, false, false)));

    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(5, 0), Some([255, 255, 255, 255]));
    assert_eq!(surface.pixel(5, 19), Some([0, 0, 0, 255]));
    assert_eq!(surface.pixel(5, 43), Some([0, 0, 0, 255]));
    assert_eq!(surface.pixel(5, 67), Some([0, 0, 0, 255]));
    assert_eq!(surface.pixel(6, 19), Some([255, 255, 255, 255]));
    assert_eq!(surface.pixel(6, 43), Some([255, 255, 255, 255]));
    assert_eq!(surface.pixel(6, 67), Some([255, 255, 255, 255]));
}

#[test]
fn native_text_decoration_combinations_share_layout_and_artifacts() {
    let document = NativeDocument::parse(
        "<style>.spacer { display:block; height:20px; } .line { display:block; width:24px; height:20px; line-height:20px; color:black; } #combo { text-decoration:underline overline; } #all { text-decoration:line-through underline overline; }</style><div class='spacer'></div><div id='combo' class='line'>A</div><div id='all' class='line'>A</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 60,
        device_scale_factor_milli: 1000,
    };
    let combo = document.resolve_target("id=combo").unwrap();
    let all = document.resolve_target("id=all").unwrap();
    let layout = document.layout(viewport).unwrap();
    let runs_for = |node_id| {
        layout
            .text_runs
            .iter()
            .filter(|run| run.node_id == node_id)
            .map(|run| (run.origin, run.text.as_str(), run.truncated))
            .collect::<Vec<_>>()
    };
    assert_eq!(
        runs_for(combo),
        vec![(NativePoint { x: 0, y: 20 }, "A", false)]
    );
    assert_eq!(
        runs_for(all),
        vec![(NativePoint { x: 0, y: 40 }, "A", false)]
    );

    let list = document.display_list(viewport).unwrap();
    let decoration_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::TextRun {
                node_id: command_node_id,
                underline,
                overline,
                line_through,
                ..
            } if *command_node_id == node_id => Some((*underline, *overline, *line_through)),
            _ => None,
        })
    };
    assert_eq!(decoration_for(combo), Some((true, true, false)));
    assert_eq!(decoration_for(all), Some((true, true, true)));

    let surface = list.rasterize().unwrap();
    for y in [19, 27, 39, 43, 47] {
        assert_eq!(surface.pixel(5, y), Some([0, 0, 0, 255]));
        assert_eq!(surface.pixel(6, y), Some([255, 255, 255, 255]));
    }
}

#[test]
fn native_text_decoration_color_separates_glyph_and_line_paint() {
    let document = NativeDocument::parse(
        "<style>#target { display:block; width:24px; height:20px; line-height:20px; color:red; text-decoration:underline overline; text-decoration-color:blue; }</style><div id='target'>A</div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 32,
        height: 20,
        device_scale_factor_milli: 1000,
    };
    let target = document.resolve_target("id=target").unwrap();
    let list = document.display_list(viewport).unwrap();
    let blue = NativeColor {
        red: 0,
        green: 0,
        blue: u8::MAX,
        alpha: u8::MAX,
    };
    let text_command = list.commands.iter().find_map(|command| match command {
        NativeDisplayCommand::TextRun {
            node_id,
            color,
            decoration_color,
            underline,
            overline,
            line_through,
            ..
        } if *node_id == target => Some((
            *color,
            *decoration_color,
            *underline,
            *overline,
            *line_through,
        )),
        _ => None,
    });
    assert_eq!(
        text_command,
        Some((NativeColor::RED, blue, true, true, false))
    );

    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(1, 0), Some([255, 0, 0, 255]));
    assert_eq!(surface.pixel(0, 7), Some([0, 0, 255, 255]));
}

#[test]
fn native_paint_color_important_priority_reaches_fill_and_text_artifacts() {
    let document = NativeDocument::parse(
        r#"<style>
            .box { display:block;width:48px;height:20px;line-height:20px;border:1px solid blue;text-decoration:underline; }
            @layer base {
                #early { background-color:red !important;color:red !important;text-decoration-color:red !important; }
                #rollback { background-color:red !important;background-color:revert-layer !important;color:red !important;color:revert-layer !important;text-decoration-color:red !important;text-decoration-color:revert-layer !important; }
                #normal { background-color:red;color:red;text-decoration-color:red; }
                #mixed { background-color:red !important;color:red !important;text-decoration-color:red !important; }
                #invalid { background-color:red !important;background-color:invalid !important;color:red !important;color:invalid !important;text-decoration-color:red !important;text-decoration-color:invalid !important; }
            }
            @layer theme {
                #early { background-color:blue !important;color:blue !important;text-decoration-color:blue !important; }
                #rollback { background-color:green !important;color:green !important;text-decoration-color:green !important; }
                #normal { background-color:blue;color:blue;text-decoration-color:blue; }
            }
            #early { background-color:green !important;color:green !important;text-decoration-color:green !important; }
            #normal { background-color:green;color:green;text-decoration-color:green; }
            #mixed { background-color:green;color:green;text-decoration-color:green; }
            #inline { background-color:red !important;color:red !important;text-decoration-color:red !important; }
        </style>
        <div id='early' class='box' role='button'>Early</div>
        <div id='rollback' class='box' role='button'>Rollback</div>
        <div id='normal' class='box' role='button'>Normal</div>
        <div id='mixed' class='box' role='button'>Mixed</div>
        <div id='invalid' class='box' role='button'>Invalid</div>
        <div id='inline' class='box' role='button' style='background-color:green !important;color:green !important;text-decoration-color:green !important'>Inline</div>"#,
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 56,
        height: 140,
        device_scale_factor_milli: 1000,
    };
    let early = document.resolve_target("id=early").unwrap();
    let rollback = document.resolve_target("id=rollback").unwrap();
    let normal = document.resolve_target("id=normal").unwrap();
    let mixed = document.resolve_target("id=mixed").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let targets = [early, rollback, normal, mixed, invalid, inline];
    let red = NativeColor::RED;
    let green = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: u8::MAX,
    };
    let layout = document.layout(viewport).unwrap();
    for node_id in targets {
        assert!(
            layout.box_for(node_id).is_some(),
            "missing paint box for {node_id:?}"
        );
    }

    let list = document.display_list(viewport).unwrap();
    let fill_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::FillRect {
                node_id: command_node_id,
                color,
                ..
            } if *command_node_id == node_id => Some(*color),
            _ => None,
        })
    };
    let text_for = |node_id| {
        list.commands.iter().find_map(|command| match command {
            NativeDisplayCommand::TextRun {
                node_id: command_node_id,
                color,
                decoration_color,
                ..
            } if *command_node_id == node_id => Some((*color, *decoration_color)),
            _ => None,
        })
    };
    for (node_id, expected) in [
        (early, red),
        (rollback, green),
        (normal, green),
        (mixed, red),
        (invalid, red),
        (inline, green),
    ] {
        assert_eq!(fill_for(node_id), Some(expected), "fill for {node_id:?}");
        assert_eq!(
            text_for(node_id),
            Some((expected, expected)),
            "text for {node_id:?}"
        );
    }
    assert_eq!(layout.hit_test(10, 10).unwrap(), Some(early));
    let early_box = layout.box_for(early).unwrap();
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(early_box.x + early_box.width - 5, early_box.y + 10),
        Some([255, 0, 0, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());

    let semantic_ids = document
        .semantic_nodes()
        .into_iter()
        .map(|node| node.node_id)
        .collect::<Vec<_>>();
    for pair in targets.windows(2) {
        assert!(
            semantic_ids.iter().position(|id| *id == pair[0])
                < semantic_ids.iter().position(|id| *id == pair[1]),
            "semantic/source order lost for {pair:?}"
        );
    }
    for detail in ["background-color", "color", "text-decoration-color"] {
        assert!(
            document.diagnostics().iter().any(|diagnostic| {
                diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
                    && diagnostic.detail == detail
            }),
            "missing diagnostic for {detail}"
        );
    }
}

#[test]
fn native_text_decoration_current_color_reaches_separate_text_artifacts() {
    let document = NativeDocument::parse(
        "<style>.line { display:block;width:64px;height:20px;line-height:20px;text-decoration:underline overline line-through; } @layer base { #local { color:red;text-decoration-color:currentColor; } #parent { display:block;width:64px;height:20px;color:green;text-decoration:underline overline line-through;text-decoration-color:red; } #black { text-decoration-color:CuRrEnTcOlOr; } #named { color:green;text-decoration-color:red; } #rollback { color:blue;text-decoration-color:red; } #invalid { color:blue;text-decoration-color:red; } #transparent { color:green;text-decoration-color:transparent; } #omitted { color:green; } } @layer theme { #named { text-decoration-color:blue; } #rollback { text-decoration-color:currentColor; } #invalid { text-decoration-color:currentColor;text-decoration-color:invalid; } } #named { text-decoration-color:revert-layer; } #rollback { text-decoration-color:revert-layer; }</style><button id='local' class='line'>Local</button><div id='parent'><button id='inherited' class='line'>Inherited</button></div><button id='black' class='line'>Black</button><button id='named' class='line'>Named</button><button id='rollback' class='line'>Rollback</button><button id='invalid' class='line'>Invalid</button><button id='inline' class='line' style='color:red;text-decoration-color:currentColor;opacity:50%'>Inline</button><button id='transparent' class='line'>Transparent</button><button id='omitted' class='line'>Omitted</button>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 80,
        height: 220,
        device_scale_factor_milli: 1000,
    };
    let local = document.resolve_target("id=local").unwrap();
    let inherited = document.resolve_target("id=inherited").unwrap();
    let black = document.resolve_target("id=black").unwrap();
    let named = document.resolve_target("id=named").unwrap();
    let rollback = document.resolve_target("id=rollback").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let inline = document.resolve_target("id=inline").unwrap();
    let transparent = document.resolve_target("id=transparent").unwrap();
    let omitted = document.resolve_target("id=omitted").unwrap();

    let green = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: u8::MAX,
    };
    let blue = NativeColor {
        red: 0,
        green: 0,
        blue: u8::MAX,
        alpha: u8::MAX,
    };
    let transparent_color = NativeColor {
        red: 0,
        green: 0,
        blue: 0,
        alpha: 0,
    };

    let layout = document.layout(viewport).unwrap();
    assert_eq!(layout.hit_test(1, 1).unwrap(), Some(local));
    assert_eq!(layout.hit_test(1, 21).unwrap(), Some(inherited));

    let list = document.display_list(viewport).unwrap();
    let command_for = |node_id| {
        list.commands
            .iter()
            .find_map(|command| match command {
                NativeDisplayCommand::TextRun {
                    node_id: command_node_id,
                    origin,
                    color,
                    decoration_color,
                    underline,
                    overline,
                    line_through,
                    clip,
                    ..
                } if *command_node_id == node_id => Some((
                    *origin,
                    *color,
                    *decoration_color,
                    *underline,
                    *overline,
                    *line_through,
                    *clip,
                )),
                _ => None,
            })
            .unwrap_or_else(|| panic!("missing text command for {node_id:?}"))
    };
    assert_eq!(command_for(local).2, NativeColor::RED);
    assert_eq!(command_for(inherited).2, green);
    assert_eq!(command_for(black).2, NativeColor::BLACK);
    assert_eq!(command_for(named).2, blue);
    assert_eq!(command_for(rollback).2, blue);
    assert_eq!(command_for(invalid).2, blue);
    assert_eq!(command_for(inline).1, NativeColor::RED);
    assert_eq!(command_for(inline).2, NativeColor::RED);
    assert_eq!(command_for(transparent).2, transparent_color);
    assert_eq!(command_for(omitted).2, green);
    for node_id in [
        local,
        inherited,
        black,
        named,
        rollback,
        invalid,
        inline,
        transparent,
        omitted,
    ] {
        let command = command_for(node_id);
        assert!(command.3 && command.4 && command.5);
        assert_eq!(command.6, None);
    }
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::BeginOpacityGroup { node_id, opacity }
                if *node_id == inline && *opacity == 128
        )
    }));

    let inline_command = command_for(inline);
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(command_for(local).0.x, command_for(local).0.y + 7),
        Some([255, 0, 0, 255])
    );
    assert_eq!(
        surface.pixel(command_for(named).0.x, command_for(named).0.y + 7),
        Some([0, 0, 255, 255])
    );
    assert_eq!(
        surface.pixel(inline_command.0.x, inline_command.0.y + 7),
        Some([255, 127, 127, 255]),
        "inline command: {inline_command:?}"
    );
    assert_eq!(
        surface.pixel(
            command_for(transparent).0.x,
            command_for(transparent).0.y + 7
        ),
        Some([255, 255, 255, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());

    let semantic_ids = document
        .semantic_nodes()
        .into_iter()
        .map(|node| node.node_id)
        .collect::<Vec<_>>();
    for pair in [
        (local, inherited),
        (inherited, black),
        (black, named),
        (named, rollback),
        (rollback, invalid),
        (invalid, inline),
        (inline, transparent),
        (transparent, omitted),
    ] {
        assert!(
            semantic_ids.iter().position(|id| *id == pair.0)
                < semantic_ids.iter().position(|id| *id == pair.1),
            "semantic/source order lost for {pair:?}"
        );
    }
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "text-decoration-color"
    }));
}

#[test]
fn native_text_decoration_color_css_wide_keywords_preserve_effective_parent_and_reset_colors() {
    let document = NativeDocument::parse(
        "<style>.line { display:block;width:80px;height:20px;line-height:20px;text-decoration:underline overline line-through; } #parent { display:block;width:96px;color:green;text-decoration:underline overline line-through;text-decoration-color:red; } #invalid { text-decoration-color:red;text-decoration-color:InHeRiT;text-decoration-color:invalid; } #inline { text-decoration-color:red; } @layer base { #named { text-decoration-color:red; } #rollback { text-decoration-color:red; } } @layer theme { .named { text-decoration-color:blue; } #rollback { text-decoration-color:blue; } } #named { text-decoration-color:revert-layer; } #rollback { text-decoration-color:revert-layer; }</style><div id='parent'><button id='inherit' class='line' style='text-decoration-color:inherit'>Inherit</button><button id='unset' class='line' style='text-decoration-color:UnSeT'>Unset</button><button id='initial' class='line' style='text-decoration-color:initial'>Initial</button><button id='revert' class='line' style='text-decoration-color:revert'>Revert</button><button id='current' class='line' style='text-decoration-color:CuRrEnTcOlOr'>Current</button><button id='invalid' class='line'>Invalid</button><button id='omitted' class='line'>Omitted</button><button id='precedence' class='line' style='text-decoration-color:inherit'>Precedence</button><button id='inline' class='line' style='color:green;text-decoration-color:blue'>Inline</button><button id='named' class='line named'>Named</button><button id='rollback' class='line'>Rollback</button></div><button id='root-inherit' class='line' style='color:red;text-decoration-color:inherit'>Root</button><div id='blue-parent' style='display:block;width:96px;color:blue;text-decoration:underline'><button id='blue-inherit' class='line' style='text-decoration-color:inherit'>Blue</button></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 112,
        height: 320,
        device_scale_factor_milli: 1000,
    };
    let green = NativeColor {
        red: 0,
        green: 128,
        blue: 0,
        alpha: u8::MAX,
    };
    let blue = NativeColor {
        red: 0,
        green: 0,
        blue: u8::MAX,
        alpha: u8::MAX,
    };
    let node_for = |id| document.resolve_target(&format!("id={id}")).unwrap();
    let command_for = |id| {
        let node_id = node_for(id);
        document
            .display_list(viewport)
            .unwrap()
            .commands
            .into_iter()
            .find_map(|command| match command {
                NativeDisplayCommand::TextRun {
                    node_id: command_node_id,
                    origin,
                    color,
                    decoration_color,
                    underline,
                    overline,
                    line_through,
                    ..
                } if command_node_id == node_id => Some((
                    origin,
                    color,
                    decoration_color,
                    underline,
                    overline,
                    line_through,
                )),
                _ => None,
            })
            .unwrap_or_else(|| panic!("missing text command for {id}"))
    };

    assert_eq!(command_for("inherit").1, green);
    assert_eq!(command_for("inherit").2, NativeColor::RED);
    for id in ["unset", "initial", "revert", "current", "omitted"] {
        assert_eq!(command_for(id).1, green, "glyph color for {id}");
        assert_eq!(command_for(id).2, green, "decoration color for {id}");
    }
    assert_eq!(command_for("precedence").1, green);
    assert_eq!(command_for("precedence").2, NativeColor::RED);
    assert_eq!(command_for("invalid").2, NativeColor::RED);
    assert_eq!(command_for("inline").1, green);
    assert_eq!(command_for("inline").2, blue);
    assert_eq!(command_for("named").2, blue);
    assert_eq!(command_for("rollback").2, blue);
    assert_eq!(command_for("root-inherit").1, NativeColor::RED);
    assert_eq!(command_for("root-inherit").2, NativeColor::BLACK);
    assert_eq!(command_for("blue-inherit").1, blue);
    assert_eq!(command_for("blue-inherit").2, blue);
    for id in [
        "inherit",
        "unset",
        "initial",
        "revert",
        "current",
        "invalid",
        "omitted",
        "precedence",
        "inline",
        "named",
        "rollback",
        "root-inherit",
        "blue-inherit",
    ] {
        let command = command_for(id);
        assert!(
            command.3 && command.4 && command.5,
            "decoration flags for {id}"
        );
    }

    let layout = document.layout(viewport).unwrap();
    for id in ["inherit", "root-inherit", "blue-inherit"] {
        let node_id = node_for(id);
        let rect = layout.box_for(node_id).unwrap();
        assert_eq!(
            layout.hit_test(i64::from(rect.x) + 1, i64::from(rect.y) + 1),
            Ok(Some(node_id))
        );
    }
    let list = document.display_list(viewport).unwrap();
    let surface = list.rasterize().unwrap();
    let inherit = command_for("inherit");
    let named = command_for("named");
    let root_inherit = command_for("root-inherit");
    assert_eq!(
        surface.pixel(inherit.0.x, inherit.0.y + 7),
        Some([255, 0, 0, 255])
    );
    assert_eq!(
        surface.pixel(named.0.x, named.0.y + 7),
        Some([0, 0, 255, 255])
    );
    assert_eq!(
        surface.pixel(root_inherit.0.x, root_inherit.0.y + 7),
        Some([0, 0, 0, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());

    let semantic_ids = document
        .semantic_nodes()
        .into_iter()
        .map(|node| node.node_id)
        .collect::<Vec<_>>();
    for pair in [
        ("inherit", "unset"),
        ("unset", "initial"),
        ("initial", "revert"),
        ("revert", "current"),
        ("current", "invalid"),
        ("invalid", "omitted"),
        ("omitted", "precedence"),
        ("precedence", "inline"),
        ("inline", "named"),
        ("named", "rollback"),
    ] {
        let first = node_for(pair.0);
        let second = node_for(pair.1);
        assert!(
            semantic_ids.iter().position(|id| *id == first)
                < semantic_ids.iter().position(|id| *id == second),
            "semantic/source order lost for {pair:?}"
        );
    }
    assert_eq!(
        document
            .diagnostics()
            .iter()
            .filter(|diagnostic| {
                diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
                    && diagnostic.detail == "text-decoration-color"
            })
            .count(),
        1
    );
}

