#[test]
fn native_order_inherit_reorders_visual_items_and_preserves_semantics() {
    let document = NativeDocument::parse(
        "<style>#outer{display:flex;width:20px;height:8px;gap:2px;align-items:flex-start;order:-3;}#first{order:0;width:4px;height:8px;flex-grow:0;flex-shrink:0;background-color:green;}#direct{order:InHeRiT;width:4px;height:8px;flex-grow:0;flex-shrink:0;background-color:red;}#omitted{width:4px;height:8px;flex-grow:0;flex-shrink:0;background-color:blue;}#invalid{display:none;order:2;order:inherit 1;}</style><div id='outer'><button id='first'>A</button><button id='direct'><span id='nested' style='display:block;height:4px'>B</span></button><button id='omitted'>C</button><button id='invalid'>D</button></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let outer = document.resolve_target("id=outer").unwrap();
    let first = document.resolve_target("id=first").unwrap();
    let direct = document.resolve_target("id=direct").unwrap();
    let nested = document.resolve_target("id=nested").unwrap();
    let omitted = document.resolve_target("id=omitted").unwrap();
    let viewport = Viewport {
        width: 24,
        height: 16,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();
    let outer_box = layout.box_for(outer).unwrap();
    let first_box = layout.box_for(first).unwrap();
    let direct_box = layout.box_for(direct).unwrap();
    let nested_box = layout.box_for(nested).unwrap();
    let omitted_box = layout.box_for(omitted).unwrap();
    assert_eq!(outer_box.width, 20);
    assert_eq!(direct_box.x, outer_box.x);
    assert_eq!(first_box.x, direct_box.x + direct_box.width + 2);
    assert_eq!(omitted_box.x, first_box.x + first_box.width + 2);
    assert_eq!(direct_box.width, 4);
    assert_eq!(nested_box.width, direct_box.width);

    let semantic_nodes = document.semantic_nodes();
    let first_position = semantic_nodes
        .iter()
        .position(|node| node.node_id == first)
        .unwrap();
    let direct_position = semantic_nodes
        .iter()
        .position(|node| node.node_id == direct)
        .unwrap();
    let omitted_position = semantic_nodes
        .iter()
        .position(|node| node.node_id == omitted)
        .unwrap();
    assert!(first_position < direct_position && direct_position < omitted_position);

    let list = document.display_list(viewport).unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == direct
                    && rect.width == direct_box.width
                    && *color == NativeColor::RED
        )
    }));
    assert_eq!(
        layout
            .hit_test(i64::from(direct_box.x + 1), i64::from(direct_box.y + 1),)
            .unwrap(),
        Some(nested)
    );
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(direct_box.x + 1, direct_box.y + 1),
        Some([255, 0, 0, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue && diagnostic.detail == "order"
    }));
}

#[test]
fn native_gap_inherit_reaches_row_column_layout_and_artifacts() {
    let document = NativeDocument::parse(
        "<style>#outer{display:flex;width:28px;height:18px;gap:3px 4px;align-items:flex-start;}#inherit{display:flex;width:12px;height:14px;flex-wrap:wrap;gap:InHeRiT;align-items:flex-start;align-content:flex-start;}#omitted{display:flex;width:12px;height:14px;flex-wrap:wrap;align-items:flex-start;align-content:flex-start;}#first,#second,#third,#omitted-first,#omitted-second,#omitted-third{width:4px;height:4px;flex-shrink:0;}#first{background-color:green;}#second{background-color:red;}#third{background-color:blue;}#omitted-first,#omitted-second,#omitted-third{background-color:#804000;}#invalid{display:none;gap:inherit 1px;}</style><div id='outer'><div id='inherit'><button id='first'>A</button><button id='second'>B</button><button id='third'>C</button></div><div id='omitted'><button id='omitted-first'>D</button><button id='omitted-second'>E</button><button id='omitted-third'>F</button></div><div id='invalid'>Invalid</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let outer = document.resolve_target("id=outer").unwrap();
    let inherited = document.resolve_target("id=inherit").unwrap();
    let first = document.resolve_target("id=first").unwrap();
    let second = document.resolve_target("id=second").unwrap();
    let third = document.resolve_target("id=third").unwrap();
    let omitted = document.resolve_target("id=omitted").unwrap();
    let omitted_first = document.resolve_target("id=omitted-first").unwrap();
    let omitted_second = document.resolve_target("id=omitted-second").unwrap();
    let omitted_third = document.resolve_target("id=omitted-third").unwrap();
    let viewport = Viewport {
        width: 36,
        height: 24,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();
    let rect = |node_id| layout.box_for(node_id).expect("layout rectangle");
    let outer_rect = rect(outer);
    let inherited_rect = rect(inherited);
    let first_rect = rect(first);
    let second_rect = rect(second);
    let third_rect = rect(third);
    let omitted_rect = rect(omitted);
    assert_eq!(outer_rect.width, 28);
    assert_eq!(inherited_rect.x, outer_rect.x);
    assert_eq!(omitted_rect.x, inherited_rect.x + inherited_rect.width + 4);
    assert_eq!(first_rect.x, inherited_rect.x);
    assert_eq!(first_rect.y, inherited_rect.y);
    assert_eq!(second_rect.x, first_rect.x + first_rect.width + 4);
    assert_eq!(second_rect.y, first_rect.y);
    assert_eq!(third_rect.x, first_rect.x);
    assert_eq!(third_rect.y, first_rect.y + first_rect.height + 3);
    assert_eq!(rect(omitted_first).x, omitted_rect.x);
    assert_eq!(rect(omitted_second).x, omitted_rect.x + 4);
    assert_eq!(rect(omitted_third).x, omitted_rect.x + 8);
    assert_eq!(rect(omitted_third).y, omitted_rect.y);

    let semantic_nodes = document.semantic_nodes();
    let source_position = |node_id| {
        semantic_nodes
            .iter()
            .position(|node| node.node_id == node_id)
            .unwrap()
    };
    assert!(source_position(first) < source_position(second));
    assert!(source_position(second) < source_position(third));

    let list = document.display_list(viewport).unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == third
                    && *rect == third_rect
                    && *color == NativeColor {
                        red: 0,
                        green: 0,
                        blue: 255,
                        alpha: 255,
                    }
        )
    }));
    assert_eq!(
        layout.hit_test(i64::from(third_rect.x + 1), i64::from(third_rect.y + 1),),
        Ok(Some(third))
    );
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(third_rect.x + 1, third_rect.y + 1),
        Some([0, 0, 255, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue && diagnostic.detail == "gap"
    }));
}

#[test]
fn native_gap_longhand_inherit_reaches_independent_axes_and_artifacts() {
    let document = NativeDocument::parse(
        "<style>#outer{display:flex;width:32px;height:18px;gap:3px 4px;align-items:flex-start;}#row{display:flex;width:14px;height:14px;flex-wrap:wrap;row-gap:inherit;column-gap:0;align-items:flex-start;align-content:flex-start;}#column{display:flex;width:14px;height:14px;flex-wrap:wrap;row-gap:0;column-gap:inherit;align-items:flex-start;align-content:flex-start;}#row-first,#row-second,#row-third,#column-first,#column-second,#column-third{width:5px;height:4px;flex-shrink:0;}#row-first{background-color:green;}#row-second{background-color:red;}#row-third{background-color:blue;}#column-first,#column-second,#column-third{background-color:#804000;}#invalid{display:none;row-gap:inherit 1px;column-gap:1px inherit;}</style><div id='outer'><div id='row'><button id='row-first'>A</button><button id='row-second'>B</button><button id='row-third'>C</button></div><div id='column'><button id='column-first'>D</button><button id='column-second'>E</button><button id='column-third'>F</button></div><div id='invalid'>Invalid</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let outer = document.resolve_target("id=outer").unwrap();
    let row = document.resolve_target("id=row").unwrap();
    let row_first = document.resolve_target("id=row-first").unwrap();
    let row_second = document.resolve_target("id=row-second").unwrap();
    let row_third = document.resolve_target("id=row-third").unwrap();
    let column = document.resolve_target("id=column").unwrap();
    let column_first = document.resolve_target("id=column-first").unwrap();
    let column_second = document.resolve_target("id=column-second").unwrap();
    let column_third = document.resolve_target("id=column-third").unwrap();
    let viewport = Viewport {
        width: 40,
        height: 24,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();
    let rect = |node_id| layout.box_for(node_id).expect("layout rectangle");
    let outer_rect = rect(outer);
    let row_rect = rect(row);
    let row_first_rect = rect(row_first);
    let row_second_rect = rect(row_second);
    let row_third_rect = rect(row_third);
    let column_rect = rect(column);
    let column_first_rect = rect(column_first);
    let column_second_rect = rect(column_second);
    let column_third_rect = rect(column_third);

    assert_eq!(outer_rect.width, 32);
    assert_eq!(row_rect.x, outer_rect.x);
    assert_eq!(column_rect.x, row_rect.x + row_rect.width + 4);
    assert_eq!(row_first_rect.x, row_rect.x);
    assert_eq!(row_first_rect.y, row_rect.y);
    assert_eq!(row_second_rect.x, row_first_rect.x + row_first_rect.width);
    assert_eq!(row_second_rect.y, row_first_rect.y);
    assert_eq!(row_third_rect.x, row_first_rect.x);
    assert_eq!(
        row_third_rect.y,
        row_first_rect.y + row_first_rect.height + 3
    );
    assert_eq!(column_first_rect.x, column_rect.x);
    assert_eq!(column_first_rect.y, column_rect.y);
    assert_eq!(
        column_second_rect.x,
        column_first_rect.x + column_first_rect.width + 4
    );
    assert_eq!(column_second_rect.y, column_first_rect.y);
    assert_eq!(column_third_rect.x, column_first_rect.x);
    assert_eq!(
        column_third_rect.y,
        column_first_rect.y + column_first_rect.height
    );

    let semantic_nodes = document.semantic_nodes();
    let source_position = |node_id| {
        semantic_nodes
            .iter()
            .position(|node| node.node_id == node_id)
            .unwrap()
    };
    assert!(source_position(row_first) < source_position(row_second));
    assert!(source_position(row_second) < source_position(row_third));

    let list = document.display_list(viewport).unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == row_third
                    && *rect == row_third_rect
                    && *color == NativeColor {
                        red: 0,
                        green: 0,
                        blue: 255,
                        alpha: 255,
                    }
        )
    }));
    assert_eq!(
        layout.hit_test(
            i64::from(row_third_rect.x + 1),
            i64::from(row_third_rect.y + 1),
        ),
        Ok(Some(row_third))
    );
    let surface = list.rasterize().unwrap();
    assert_eq!(
        surface.pixel(row_third_rect.x + 1, row_third_rect.y + 1),
        Some([0, 0, 255, 255])
    );
    assert!(!surface.to_png().unwrap().is_empty());
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && (diagnostic.detail == "row-gap" || diagnostic.detail == "column-gap")
    }));
}

#[test]
fn native_flex_shorthand_expands_zero_basis_and_preserves_shared_consumers() {
    let document = NativeDocument::parse(
        "<div id='row' style='display:flex;width:20px;gap:2px'><div id='first' style='width:100px;height:8px;flex:1;background-color:red'><span id='nested' style='display:block;height:4px'>A</span></div><div id='second' style='width:100px;height:8px;flex:1;background-color:blue'>B</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let row = document.resolve_target("id=row").unwrap();
    let first = document.resolve_target("id=first").unwrap();
    let nested = document.resolve_target("id=nested").unwrap();
    let second = document.resolve_target("id=second").unwrap();
    let viewport = Viewport {
        width: 24,
        height: 32,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();

    assert_eq!(layout.box_for(row).unwrap().width, 20);
    assert_eq!(layout.box_for(first).unwrap().x, 0);
    assert_eq!(layout.box_for(first).unwrap().width, 9);
    assert_eq!(layout.box_for(nested).unwrap().width, 9);
    assert_eq!(layout.box_for(second).unwrap().x, 11);
    assert_eq!(layout.box_for(second).unwrap().width, 9);

    let list = document.display_list(viewport).unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == first && rect.width == 9 && *color == NativeColor::RED
        )
    }));
    assert_eq!(layout.hit_test(8, 6).unwrap(), Some(first));
    assert_eq!(layout.hit_test(11, 1).unwrap(), Some(second));
}

#[test]
fn native_flex_sizing_css_wide_resets_reach_layout_and_raster() {
    let document = NativeDocument::parse(
        "<style>.row { display:flex; width:32px; height:8px; gap:2px; align-items:flex-start; } .item { width:4px; height:4px; flex-shrink:0; } #reset { flex:4 5 12px; background-color:red; } #reset { flex:InItIaL; } #longhands { flex-grow:4; flex-shrink:5; flex-basis:12px; background-color:green; } #longhands { flex-grow:UnSeT; } #longhands { flex-shrink:ReVeRt; flex-basis:INITIAL; } #invalid { flex:2 3 8px; background-color:blue; } #invalid { flex:inherit 1 auto; } #important { flex:5 6 10px !important; background-color:black; } #important { flex:initial; }</style><div id='row' class='row'><div id='reset' class='item'>A</div><div id='longhands' class='item'>B</div><div id='invalid' class='item'>C</div><div id='important' class='item'>D</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 40,
        height: 16,
        device_scale_factor_milli: 1000,
    };
    let row = document.resolve_target("id=row").unwrap();
    let reset = document.resolve_target("id=reset").unwrap();
    let longhands = document.resolve_target("id=longhands").unwrap();
    let invalid = document.resolve_target("id=invalid").unwrap();
    let important = document.resolve_target("id=important").unwrap();

    let layout = document.layout(viewport).unwrap();
    assert_eq!(layout.box_for(row).unwrap().width, 32);
    let rect = |node_id| layout.box_for(node_id).expect("layout rectangle");
    let reset_rect = rect(reset);
    let longhands_rect = rect(longhands);
    let invalid_rect = rect(invalid);
    let important_rect = rect(important);
    assert_eq!(
        reset_rect,
        NativeRect {
            x: 0,
            y: 0,
            width: 4,
            height: 4
        }
    );
    assert_eq!(
        longhands_rect,
        NativeRect {
            x: 6,
            y: 0,
            width: 4,
            height: 4
        }
    );
    assert_eq!(
        invalid_rect,
        NativeRect {
            x: 12,
            y: 0,
            width: 8,
            height: 4
        }
    );
    assert_eq!(
        important_rect,
        NativeRect {
            x: 22,
            y: 0,
            width: 10,
            height: 4
        }
    );

    let list = document.display_list(viewport).unwrap();
    for (node_id, rect, color) in [
        (reset, reset_rect, NativeColor::RED),
        (
            longhands,
            longhands_rect,
            NativeColor {
                red: 0,
                green: 128,
                blue: 0,
                alpha: u8::MAX,
            },
        ),
        (
            invalid,
            invalid_rect,
            NativeColor {
                red: 0,
                green: 0,
                blue: u8::MAX,
                alpha: u8::MAX,
            },
        ),
        (important, important_rect, NativeColor::BLACK),
    ] {
        assert!(list.commands.iter().any(|command| {
            matches!(
                command,
                NativeDisplayCommand::FillRect { node_id: command_node, rect: command_rect, color: command_color, .. }
                    if *command_node == node_id && *command_rect == rect && *command_color == color
            )
        }));
    }
    assert_eq!(layout.hit_test(1, 1).unwrap(), Some(reset));
    assert_eq!(layout.hit_test(23, 1).unwrap(), Some(important));
    let surface = list.rasterize().unwrap();
    assert_eq!(surface.pixel(1, 1), Some([255, 0, 0, 255]));
    assert_eq!(surface.pixel(23, 1), Some([0, 0, 0, 255]));
    assert!(!surface.to_png().unwrap().is_empty());
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue && diagnostic.detail == "flex"
    }));
}

#[test]
fn native_flex_flow_css_wide_resets_reach_layout_and_raster() {
    let document = NativeDocument::parse(
        "<style>.flex { display:flex; width:8px; height:8px; gap:2px; align-items:flex-start; } .item { width:4px; height:4px; flex-shrink:0; } #direction { flex-direction:column; } #direction { flex-direction:INITIAL; } #wrap { flex-wrap:wrap; } #wrap { flex-wrap:UNSET; } #flow { flex-flow:column wrap; } #flow { flex-flow:ReVeRt; } #invalid { flex-flow:row-reverse wrap; } #invalid { flex-flow:inherit row; } #important { flex-flow:column wrap !important; } #important { flex-flow:initial; }</style><div id='direction' class='flex'><button id='direction-first' class='item' style='background-color:red'>A</button><button id='direction-second' class='item' style='background-color:blue'>B</button></div><div id='wrap' class='flex'><div id='wrap-first' class='item' style='background-color:red'>A</div><div id='wrap-second' class='item' style='background-color:blue'>B</div></div><div id='flow' class='flex'><div id='flow-first' class='item' style='background-color:red'>A</div><div id='flow-second' class='item' style='background-color:blue'>B</div></div><div id='invalid' class='flex'><div id='invalid-first' class='item' style='background-color:green'>A</div><div id='invalid-second' class='item' style='background-color:black'>B</div></div><div id='important' class='flex'><div id='important-first' class='item' style='background-color:red'>A</div><div id='important-second' class='item' style='background-color:blue'>B</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let viewport = Viewport {
        width: 24,
        height: 48,
        device_scale_factor_milli: 1000,
    };
    let direction = document.resolve_target("id=direction").unwrap();
    let direction_first = document.resolve_target("id=direction-first").unwrap();
    let direction_second = document.resolve_target("id=direction-second").unwrap();
    let wrap = document.resolve_target("id=wrap").unwrap();
    let wrap_first = document.resolve_target("id=wrap-first").unwrap();
    let wrap_second = document.resolve_target("id=wrap-second").unwrap();
    let flow = document.resolve_target("id=flow").unwrap();
    let flow_first = document.resolve_target("id=flow-first").unwrap();
    let flow_second = document.resolve_target("id=flow-second").unwrap();
    let invalid_first = document.resolve_target("id=invalid-first").unwrap();
    let invalid_second = document.resolve_target("id=invalid-second").unwrap();
    let important = document.resolve_target("id=important").unwrap();
    let important_first = document.resolve_target("id=important-first").unwrap();
    let important_second = document.resolve_target("id=important-second").unwrap();

    let layout = document.layout(viewport).unwrap();
    let rect = |node_id| layout.box_for(node_id).expect("layout rectangle");
    let direction_rect = rect(direction);
    let direction_first_rect = rect(direction_first);
    let direction_second_rect = rect(direction_second);
    assert_eq!(direction_rect.width, 8);
    assert_eq!(direction_rect.height, 8);
    assert_eq!(direction_first_rect.x, direction_rect.x);
    assert_eq!(direction_second_rect.x, direction_rect.x + 6);
    assert_eq!(direction_second_rect.y, direction_first_rect.y);

    let wrap_rect = rect(wrap);
    let wrap_first_rect = rect(wrap_first);
    let wrap_second_rect = rect(wrap_second);
    assert_eq!(wrap_second_rect.x, wrap_rect.x + 6);
    assert_eq!(wrap_second_rect.y, wrap_first_rect.y);

    let flow_rect = rect(flow);
    let flow_first_rect = rect(flow_first);
    let flow_second_rect = rect(flow_second);
    assert_eq!(flow_second_rect.x, flow_rect.x + 6);
    assert_eq!(flow_second_rect.y, flow_first_rect.y);

    let invalid_first_rect = rect(invalid_first);
    let invalid_second_rect = rect(invalid_second);
    assert!(invalid_second_rect.y > invalid_first_rect.y);

    let important_rect = rect(important);
    let important_first_rect = rect(important_first);
    let important_second_rect = rect(important_second);
    assert_eq!(important_second_rect.x, important_rect.x + 6);
    assert_eq!(important_second_rect.y, important_first_rect.y);

    let semantic_nodes = document.semantic_nodes();
    assert!(
        semantic_nodes
            .iter()
            .position(|semantic_node| semantic_node.node_id == direction_first)
            < semantic_nodes
                .iter()
                .position(|semantic_node| semantic_node.node_id == direction_second)
    );

    let list = document.display_list(viewport).unwrap();
    let surface = list.rasterize().unwrap();
    for (node_id, node_rect, color) in [
        (direction_first, direction_first_rect, [255, 0, 0, 255]),
        (direction_second, direction_second_rect, [0, 0, 255, 255]),
        (invalid_first, invalid_first_rect, [0, 128, 0, 255]),
        (invalid_second, invalid_second_rect, [0, 0, 0, 255]),
    ] {
        assert!(list.commands.iter().any(|command| {
            matches!(
                command,
                NativeDisplayCommand::FillRect { node_id: command_node, rect: command_rect, .. }
                    if *command_node == node_id && *command_rect == node_rect
            )
        }));
        assert_eq!(surface.pixel(node_rect.x + 1, node_rect.y + 1), Some(color));
    }
    assert_eq!(
        layout
            .hit_test(
                i64::from(direction_first_rect.x + 1),
                i64::from(direction_first_rect.y + 1),
            )
            .unwrap(),
        Some(direction_first)
    );
    assert_eq!(
        layout
            .hit_test(
                i64::from(important_second_rect.x + 1),
                i64::from(important_second_rect.y + 1),
            )
            .unwrap(),
        Some(important_second)
    );
    assert!(!surface.to_png().unwrap().is_empty());
    assert!(document.diagnostics().iter().any(|diagnostic| {
        diagnostic.code == NativeDiagnosticCode::UnsupportedCssValue
            && diagnostic.detail == "flex-flow"
    }));
}

#[test]
fn native_flex_flow_shorthand_reuses_reverse_and_wrap_consumers() {
    let document = NativeDocument::parse(
        "<div id='row' style='display:flex;width:12px;gap:2px;flex-flow:row-reverse wrap'><div id='first' style='width:8px;height:6px;margin:1px;flex-shrink:0;background-color:red'>A</div><div id='second' style='width:4px;height:6px;margin:1px;flex-shrink:0;background-color:blue'>B</div></div>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let row = document.resolve_target("id=row").unwrap();
    let first = document.resolve_target("id=first").unwrap();
    let second = document.resolve_target("id=second").unwrap();
    let viewport = Viewport {
        width: 16,
        height: 24,
        device_scale_factor_milli: 1000,
    };
    let layout = document.layout(viewport).unwrap();

    assert_eq!(layout.box_for(row).unwrap().width, 12);
    assert_eq!(
        layout.box_for(first),
        Some(NativeRect {
            x: 3,
            y: 1,
            width: 8,
            height: 6,
        })
    );
    assert_eq!(
        layout.box_for(second),
        Some(NativeRect {
            x: 7,
            y: 11,
            width: 4,
            height: 6,
        })
    );

    let list = document.display_list(viewport).unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect { node_id, rect, color, .. }
                if *node_id == first && rect.x == 3 && rect.y == 1 && *color == NativeColor::RED
        )
    }));
    assert_eq!(layout.hit_test(4, 2).unwrap(), Some(first));
    assert_eq!(layout.hit_test(8, 12).unwrap(), Some(second));
}

#[tokio::test]
async fn legacy_name_fragments_use_decoded_fallback_and_preserve_scroll_safety() {
    let html = "<a id='jump' href='#legacy%20plan'>Jump</a><p>one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen</p><p>seventeen eighteen nineteen twenty twenty-one twenty-two twenty-three twenty-four twenty-five twenty-six</p><a name='legacy plan'>Legacy target</a><a name='café'>UTF-8 legacy target</a><a name='same'>Name should lose</a><a name='hidden' style='display:none'>Hidden legacy target</a><a name='zero' style='display:contents'></a><a name='duplicate'>First duplicate</a><a name='duplicate'>Second duplicate</a><div name='not-anchor'>Not a target</div><p id='same'>ID target</p>";
    let viewport = Viewport {
        width: 160,
        height: 40,
        device_scale_factor_milli: 1000,
    };
    let expected_document = NativeDocument::parse(html, &NativeEngineLimits::default()).unwrap();
    let expected_layout = expected_document.layout(viewport).unwrap();
    let legacy = find_element_with_attribute(&expected_document, "a", "name", "legacy plan");
    let legacy_scroll = NativePoint {
        x: 0,
        y: expected_layout
            .box_for(legacy)
            .expect("legacy anchor layout")
            .y
            .min(expected_layout.max_scroll_offset().y),
    };
    assert!(legacy_scroll.y > 0);

    let config = NativeEngineConfig::default()
        .with_viewport(viewport)
        .with_fixture("fixture://name-fragments", html)
        .unwrap()
        .with_initial_url("fixture://name-fragments");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let jumped = engine
        .action(NativeAction::Click {
            target: "id=jump".into(),
        })
        .unwrap();
    assert!(jumped.accepted);
    assert_eq!(engine.scroll_offset(), legacy_scroll);
    assert_eq!(
        engine.snapshot().unwrap().url,
        "fixture://name-fragments#legacy%20plan"
    );

    let initial = engine.go_back().unwrap().unwrap();
    assert_eq!(initial.url, "fixture://name-fragments");
    assert_eq!(engine.scroll_offset(), NativePoint { x: 0, y: 0 });
    let restored = engine.go_forward().unwrap().unwrap();
    assert_eq!(restored.url, "fixture://name-fragments#legacy%20plan");
    assert_eq!(engine.scroll_offset(), legacy_scroll);

    engine
        .navigate("fixture://name-fragments#caf%C3%A9")
        .unwrap();
    let utf8_target = find_element_with_attribute(&expected_document, "a", "name", "café");
    assert_eq!(
        engine.scroll_offset().y,
        expected_layout
            .box_for(utf8_target)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y)
    );

    engine.navigate("fixture://name-fragments#same").unwrap();
    let id_target = expected_document.resolve_target("id=same").unwrap();
    assert_eq!(
        engine.scroll_offset().y,
        expected_layout
            .box_for(id_target)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y)
    );
    for fragment in [
        "duplicate",
        "not-anchor",
        "DUPLICATE",
        "hidden",
        "zero",
        "missing",
    ] {
        let before = engine.scroll_offset();
        engine
            .navigate(format!("fixture://name-fragments#{fragment}"))
            .unwrap();
        assert_eq!(engine.scroll_offset(), before, "fragment={fragment}");
    }
}

#[tokio::test]
async fn text_fragments_match_bounded_visible_runs_and_fail_closed() {
    let html = "<a id='jump' href='#:~:text=target%20phrase,anchor'>Jump</a><p>one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen</p><p>seventeen eighteen nineteen twenty twenty-one twenty-two twenty-three twenty-four twenty-five twenty-six</p><p style='white-space:pre'>target phrase anchor and more</p><p style='white-space:pre'>comma, target phrase</p><p style='white-space:pre'>repeat target</p><p style='white-space:pre'>repeat target</p><p>cross <span>run target</span></p><p style='display:none'>hidden target</p><p style='white-space:pre'>plus a+b</p>";
    let viewport = Viewport {
        width: 240,
        height: 40,
        device_scale_factor_milli: 1000,
    };
    let expected_document = NativeDocument::parse(html, &NativeEngineLimits::default()).unwrap();
    let expected_layout = expected_document.layout(viewport).unwrap();
    let range_run = expected_layout
        .text_runs
        .iter()
        .find(|run| run.text.contains("target phrase") && run.text.contains("anchor"))
        .unwrap();
    let range_scroll = NativePoint {
        x: 0,
        y: expected_layout
            .box_for(range_run.node_id)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y),
    };
    assert!(range_scroll.y > 0);

    let config = NativeEngineConfig::default()
        .with_viewport(viewport)
        .with_fixture("fixture://text-fragments", html)
        .unwrap()
        .with_initial_url("fixture://text-fragments");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let jumped = engine
        .action(NativeAction::Click {
            target: "id=jump".into(),
        })
        .unwrap();
    assert!(jumped.accepted);
    assert_eq!(engine.scroll_offset(), range_scroll);
    assert_eq!(
        engine.snapshot().unwrap().url,
        "fixture://text-fragments#:~:text=target%20phrase,anchor"
    );

    let initial = engine.go_back().unwrap().unwrap();
    assert_eq!(initial.url, "fixture://text-fragments");
    assert_eq!(engine.scroll_offset(), NativePoint { x: 0, y: 0 });
    let restored = engine.go_forward().unwrap().unwrap();
    assert_eq!(
        restored.url,
        "fixture://text-fragments#:~:text=target%20phrase,anchor"
    );
    assert_eq!(engine.scroll_offset(), range_scroll);

    let comma_run = expected_layout
        .text_runs
        .iter()
        .find(|run| run.text.contains("comma, target phrase"))
        .unwrap();
    engine
        .navigate("fixture://text-fragments#:~:text=comma%2C%20target%20phrase")
        .unwrap();
    assert_eq!(
        engine.scroll_offset().y,
        expected_layout
            .box_for(comma_run.node_id)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y)
    );

    let plus_run = expected_layout
        .text_runs
        .iter()
        .find(|run| run.text.contains("plus a+b"))
        .unwrap();
    engine
        .navigate("fixture://text-fragments#:~:text=plus%20a%2Bb")
        .unwrap();
    assert_eq!(
        engine.scroll_offset().y,
        expected_layout
            .box_for(plus_run.node_id)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y)
    );

    let first_repeat = expected_layout
        .text_runs
        .iter()
        .find(|run| run.text.contains("repeat target"))
        .unwrap();
    engine
        .navigate("fixture://text-fragments#:~:text=repeat%20target")
        .unwrap();
    assert_eq!(
        engine.scroll_offset().y,
        expected_layout
            .box_for(first_repeat.node_id)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y)
    );

    for fragment in [
        ":~:text=hidden%20target",
        ":~:text=cross,target",
        ":~:text=anchor,target",
        ":~:text=prefix-,target",
        ":~:text=target,-suffix",
        ":~:text=target,end,extra",
        ":~:text=bad%ZZ",
        ":~:text=bad%C3%28",
        ":~:text=missing",
    ] {
        let before = engine.scroll_offset();
        engine
            .navigate(format!("fixture://text-fragments#{fragment}"))
            .unwrap();
        assert_eq!(engine.scroll_offset(), before, "fragment={fragment}");
    }
}

#[tokio::test]
async fn text_fragment_affixes_match_adjacent_terms_and_fail_closed() {
    let html = "<a id='jump' href='#:~:text=prefix%20-,target%20phrase,anchor,-%20suffix'>Jump</a><p>one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen</p><p>seventeen eighteen nineteen twenty twenty-one twenty-two twenty-three twenty-four twenty-five twenty-six</p><p style='white-space:pre'>prefix target phrase anchor suffix</p><p style='white-space:pre'>prefix target phrase mismatch</p><p style='white-space:pre'>target phrase anchor suffix</p><p>cross <span>target phrase</span></p><p style='display:none'>prefix target phrase anchor suffix</p><p style='white-space:pre'>target phrase anchor</p>";
    let viewport = Viewport {
        width: 240,
        height: 40,
        device_scale_factor_milli: 1000,
    };
    let expected_document = NativeDocument::parse(html, &NativeEngineLimits::default()).unwrap();
    let expected_layout = expected_document.layout(viewport).unwrap();
    let affix_run = expected_layout
        .text_runs
        .iter()
        .find(|run| run.text == "prefix target phrase anchor suffix")
        .unwrap();
    let affix_scroll = NativePoint {
        x: 0,
        y: expected_layout
            .box_for(affix_run.node_id)
            .unwrap()
            .y
            .min(expected_layout.max_scroll_offset().y),
    };
    assert!(affix_scroll.y > 0);

    let config = NativeEngineConfig::default()
        .with_viewport(viewport)
        .with_fixture("fixture://text-affixes", html)
        .unwrap()
        .with_initial_url("fixture://text-affixes");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let jumped = engine
        .action(NativeAction::Click {
            target: "id=jump".into(),
        })
        .unwrap();
    assert!(jumped.accepted);
    assert_eq!(engine.scroll_offset(), affix_scroll);
    assert_eq!(
        engine.snapshot().unwrap().url,
        "fixture://text-affixes#:~:text=prefix%20-,target%20phrase,anchor,-%20suffix"
    );

    let initial = engine.go_back().unwrap().unwrap();
    assert_eq!(initial.url, "fixture://text-affixes");
    assert_eq!(engine.scroll_offset(), NativePoint { x: 0, y: 0 });
    let restored = engine.go_forward().unwrap().unwrap();
    assert_eq!(
        restored.url,
        "fixture://text-affixes#:~:text=prefix%20-,target%20phrase,anchor,-%20suffix"
    );
    assert_eq!(engine.scroll_offset(), affix_scroll);

    for fragment in [
        ":~:text=target%20phrase",
        ":~:text=target%20phrase,anchor",
        ":~:text=prefix%20-,target%20phrase",
        ":~:text=target%20phrase,-%20suffix",
        ":~:text=prefix%20-,target%20phrase,-%20suffix",
        ":~:text=prefix%20-,target%20phrase,anchor",
        ":~:text=target%20phrase,anchor,-%20suffix",
        ":~:text=prefix%20-,target%20phrase,anchor,-%20suffix",
    ] {
        engine
            .navigate(format!("fixture://text-affixes#{fragment}"))
            .unwrap();
        assert_eq!(engine.scroll_offset(), affix_scroll, "fragment={fragment}");
    }

    for fragment in [
        ":~:text=prefix-,target%20phrase",
        ":~:text=target%20phrase,-suffix",
        ":~:text=wrong%20-,target%20phrase",
        ":~:text=target%20phrase,-%20wrong",
        ":~:text=anchor,target%20phrase",
        ":~:text=cross,target",
        ":~:text=hidden%20-,target%20phrase",
        ":~:text=target%20phrase,anchor,extra",
        ":~:text=prefix%20-,target%20phrase,anchor,extra",
        ":~:text=prefix%20-,target%20phrase,-%20suffix,extra",
        ":~:text=target%20phrase,anchor,-",
        ":~:text=bad%ZZ,target",
    ] {
        let before = engine.scroll_offset();
        engine
            .navigate(format!("fixture://text-affixes#{fragment}"))
            .unwrap();
        assert_eq!(engine.scroll_offset(), before, "fragment={fragment}");
    }
}

#[tokio::test]
async fn semantic_actions_and_effects_use_the_backend_contract() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://controls",
            "<label for='name'>Name</label><input id='name' type='text'><button id='save'>Save</button><input id='remember' type='checkbox'>",
        )
        .unwrap()
        .with_initial_url("fixture://controls");
    let backend = NativeEngineBackend::new(config).unwrap();
    let dispatcher = BrowserBackendDispatcher::new(&backend);
    dispatcher.initialize().await.unwrap();

    let clicked = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Click {
                target: "id=remember".into(),
            },
        })
        .await
        .unwrap();
    assert_eq!(clicked.revision, 2);
    assert!(clicked.accepted);

    let click_effects = dispatcher
        .effects(EffectsRequest {
            context_id: "native-context".into(),
            since_revision: 1,
        })
        .await
        .unwrap();
    assert_eq!(click_effects.revision, 2);
    assert!(click_effects.changed);

    let typed = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::Type {
                target: "id=name".into(),
                text: "Glass".into(),
            },
        })
        .await
        .unwrap();
    assert_eq!(typed.revision, 3);

    let unchanged = dispatcher
        .effects(EffectsRequest {
            context_id: "native-context".into(),
            since_revision: 3,
        })
        .await
        .unwrap();
    assert_eq!(unchanged.revision, 3);
    assert!(!unchanged.changed);

    let keypress = dispatcher
        .action(ActionRequest {
            context_id: "native-context".into(),
            action: SemanticAction::KeyPress { key: "!".into() },
        })
        .await
        .unwrap();
    assert_eq!(keypress.revision, 4);
    assert!(keypress.accepted);

    let future = dispatcher
        .effects(EffectsRequest {
            context_id: "native-context".into(),
            since_revision: 5,
        })
        .await
        .unwrap_err();
    assert!(matches!(
        future,
        glass_browser::browser_backend::BrowserBackendError::InvalidConfiguration { field, .. }
            if field == "since revision"
    ));
    dispatcher.close().await.unwrap();
}

#[tokio::test]
async fn semantic_storage_uses_bounded_native_backend_state() {
    let backend = NativeEngineBackend::new(NativeEngineConfig::default()).unwrap();
    assert_eq!(
        backend
            .profile()
            .capability(BrowserCapability::Storage)
            .level,
        SupportLevel::Available
    );
    let dispatcher = BrowserBackendDispatcher::new(&backend);
    dispatcher.initialize().await.unwrap();

    let written = dispatcher
        .storage(StorageRequest {
            context_id: "native-context".into(),
            scope: StorageScope::Local,
            operation: StorageOperation::Write {
                key: "theme".into(),
                value: "dark".into(),
            },
        })
        .await
        .unwrap();
    assert_eq!(written.entries.get("theme"), Some(&"dark".to_owned()));

    let session = dispatcher
        .storage(StorageRequest {
            context_id: "native-context".into(),
            scope: StorageScope::Session,
            operation: StorageOperation::Write {
                key: "tab".into(),
                value: "one".into(),
            },
        })
        .await
        .unwrap();
    assert_eq!(session.entries.get("tab"), Some(&"one".to_owned()));

    let local = dispatcher
        .storage(StorageRequest {
            context_id: "native-context".into(),
            scope: StorageScope::Local,
            operation: StorageOperation::Read,
        })
        .await
        .unwrap();
    assert_eq!(local.entries.get("theme"), Some(&"dark".to_owned()));
    assert!(!local.entries.contains_key("tab"));

    let cleared = dispatcher
        .storage(StorageRequest {
            context_id: "native-context".into(),
            scope: StorageScope::Local,
            operation: StorageOperation::Clear,
        })
        .await
        .unwrap();
    assert!(cleared.entries.is_empty());

    let cookie_error = dispatcher
        .storage(StorageRequest {
            context_id: "native-context".into(),
            scope: StorageScope::Cookies,
            operation: StorageOperation::Read,
        })
        .await
        .unwrap_err();
    assert!(matches!(
        cookie_error,
        glass_browser::browser_backend::BrowserBackendError::UnsupportedOperation { operation, .. }
            if operation == "storage"
    ));
    dispatcher.close().await.unwrap();
}

#[test]
fn native_backend_requires_explicit_factory_selection() {
    let automatic = BackendSelectionRequest {
        schema_version: BROWSER_BACKEND_SCHEMA_VERSION,
        glass_version: env!("CARGO_PKG_VERSION").into(),
        preferred_backend_id: None,
        browser_family: None,
        browser_version: None,
        required_capabilities: vec![],
        minimum_certification: CertificationLevel::Experimental,
    };
    let native = BackendFactory::native(NativeEngineConfig::default()).unwrap();
    assert!(BackendFactory::start(&automatic, vec![native]).is_err());

    let explicit = BackendSelectionRequest {
        preferred_backend_id: Some(NATIVE_ENGINE_BACKEND_ID.into()),
        ..automatic
    };
    let native = BackendFactory::native(NativeEngineConfig::default()).unwrap();
    let started = BackendFactory::start(&explicit, vec![native]).unwrap();
    assert_eq!(
        started.profile().identity.backend_id,
        NATIVE_ENGINE_BACKEND_ID
    );
}

#[test]
fn lifecycle_state_is_terminal_after_close() {
    let mut engine = glass_browser::NativeEngine::new(NativeEngineConfig::default()).unwrap();
    assert_eq!(engine.lifecycle(), NativeLifecycleState::New);
    assert_eq!(engine.runtime_state(), NativeRuntimeState::New);
    engine.initialize().unwrap();
    assert_eq!(engine.lifecycle(), NativeLifecycleState::Running);
    assert_eq!(engine.runtime_state(), NativeRuntimeState::Running);
    let running_trace = engine.runtime_trace();
    assert!(
        running_trace
            .iter()
            .any(|event| event.kind == NativeRuntimeTraceKind::Started)
    );
    assert!(
        running_trace
            .iter()
            .any(|event| event.kind == NativeRuntimeTraceKind::TaskReady)
    );
    engine.close().unwrap();
    assert_eq!(engine.lifecycle(), NativeLifecycleState::Closed);
    assert_eq!(engine.runtime_state(), NativeRuntimeState::Closed);
    let closed_trace = engine.runtime_trace();
    assert!(
        closed_trace
            .iter()
            .any(|event| event.kind == NativeRuntimeTraceKind::CancellationRequested)
    );
    assert!(
        closed_trace
            .iter()
            .any(|event| event.kind == NativeRuntimeTraceKind::Closed)
    );
    assert!(engine.initialize().is_err());
    assert!(engine.close().is_err());
}

#[test]
fn semantic_dom_references_and_locators_are_revision_bound() {
    let document = NativeDocument::parse(
        "<label for='query'>Query</label><input id='query' type='search'><button id='go'>Go</button>",
        &NativeEngineLimits::default(),
    )
    .unwrap();
    let nodes = document.semantic_nodes();
    let query = nodes.iter().find(|node| node.role == "textbox").unwrap();
    assert_eq!(query.name, "Query");
    assert_eq!(document.resolve_target("id=query"), Ok(query.node_id));
    assert_eq!(
        document.resolve_target("role=textbox[name=Query]"),
        Ok(query.node_id)
    );
    assert_eq!(
        query.reference,
        format!("ref=r1:n{}", query.node_id.index())
    );
    assert!(document.resolve_target(&query.reference).is_ok());
}

#[test]
fn native_actions_update_state_and_reject_unsafe_targets_before_mutation() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://controls",
            "<label for='name'>Name</label><input id='name' type='text'><input id='remember' type='checkbox'><input id='first' type='radio' name='choice'><input id='second' type='radio' name='choice' checked><input id='disabled' type='text' disabled><input id='readonly' type='text' readonly><button id='save'>Save</button><button id='other'>Other</button><p id='plain'>Plain</p><select id='country'><option id='one' value='one'>One</option><option id='two' value='two'>Two</option></select><select id='many' multiple><option id='many-one'>Many One</option></select>",
        )
        .unwrap()
        .with_initial_url("fixture://controls");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let initial_nodes = engine.semantic_nodes().unwrap();
    let remember_reference = initial_nodes
        .iter()
        .find(|node| node.role == "checkbox")
        .map(|node| node.reference.clone())
        .unwrap();
    assert_eq!(engine.revision(), 1);

    let click = engine
        .action(NativeAction::Click {
            target: "id=remember".into(),
        })
        .unwrap();
    assert_eq!(click.revision, 2);
    let after_click = engine.semantic_nodes().unwrap();
    let remember = after_click
        .iter()
        .find(|node| node.role == "checkbox")
        .unwrap();
    assert_eq!(remember.checked, Some(true));
    assert!(remember.focused);
    let click_effects = engine.effects_since(1).unwrap();
    assert_eq!(
        click_effects
            .effects
            .iter()
            .map(|effect| effect.kind)
            .collect::<Vec<_>>(),
        vec![
            NativeEventKind::Focus,
            NativeEventKind::Click,
            NativeEventKind::Change
        ]
    );

    let typed = engine
        .action(NativeAction::Type {
            target: "id=name".into(),
            text: "Glass".into(),
        })
        .unwrap();
    assert_eq!(typed.revision, 3);
    let after_type = engine.semantic_nodes().unwrap();
    let name = after_type.iter().find(|node| node.name == "Name").unwrap();
    let remember = after_type
        .iter()
        .find(|node| node.role == "checkbox")
        .unwrap();
    assert_eq!(name.empty, Some(false));
    assert!(name.focused);
    assert!(!remember.focused);

    engine
        .action(NativeAction::Click {
            target: "id=first".into(),
        })
        .unwrap();
    let radios = engine.semantic_nodes().unwrap();
    assert_eq!(
        radios
            .iter()
            .find(|node| node.role == "radio")
            .and_then(|node| node.checked),
        Some(true)
    );
    assert_eq!(
        radios
            .iter()
            .filter(|node| node.role == "radio")
            .nth(1)
            .and_then(|node| node.checked),
        Some(false)
    );

    let options = engine.semantic_nodes().unwrap();
    assert_eq!(
        options
            .iter()
            .find(|node| node.name == "One")
            .and_then(|node| node.selected),
        Some(true)
    );
    assert_eq!(
        options
            .iter()
            .find(|node| node.name == "Two")
            .and_then(|node| node.selected),
        Some(false)
    );
    assert_eq!(
        options
            .iter()
            .find(|node| node.role == "combobox" && node.tag_name == "select")
            .and_then(|node| node.empty),
        Some(false)
    );
    let selected = engine
        .action(NativeAction::Click {
            target: "id=two".into(),
        })
        .unwrap();
    assert_eq!(selected.revision, 5);
    let selected_options = engine.semantic_nodes().unwrap();
    assert_eq!(
        selected_options
            .iter()
            .find(|node| node.name == "One")
            .and_then(|node| node.selected),
        Some(false)
    );
    assert_eq!(
        selected_options
            .iter()
            .find(|node| node.name == "Two")
            .and_then(|node| node.selected),
        Some(true)
    );

    assert!(matches!(
        engine.action(NativeAction::Click {
            target: "role=button".into(),
        }),
        Err(glass_browser::NativeEngineError::AmbiguousTarget { matches: 2 })
    ));
    assert!(matches!(
        engine.action(NativeAction::Click {
            target: "id=plain".into(),
        }),
        Err(glass_browser::NativeEngineError::TargetNotActionable { .. })
    ));
    let multi_selected = engine
        .action(NativeAction::Click {
            target: "id=many-one".into(),
        })
        .unwrap();
    assert_eq!(multi_selected.revision, 6);
    assert_eq!(
        engine
            .semantic_nodes()
            .unwrap()
            .iter()
            .filter(|node| node.role == "option")
            .nth(2)
            .and_then(|node| node.selected),
        Some(true)
    );
    let revision_before_rejections = engine.revision();
    assert!(matches!(
        engine.action(NativeAction::Click {
            target: remember_reference,
        }),
        Err(glass_browser::NativeEngineError::DetachedTarget)
    ));
    assert!(matches!(
        engine.action(NativeAction::Click {
            target: "id=disabled".into(),
        }),
        Err(glass_browser::NativeEngineError::DisabledTarget)
    ));
    assert!(matches!(
        engine.action(NativeAction::Type {
            target: "id=readonly".into(),
            text: "nope".into(),
        }),
        Err(glass_browser::NativeEngineError::ReadOnlyTarget)
    ));
    assert_eq!(engine.revision(), revision_before_rejections);
}

#[test]
fn visibility_projection_and_actionability_are_consistent() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://visibility",
            "<button id='visible'>Visible</button><button id='hidden' hidden>Hidden</button><button id='aria' aria-hidden='true'>Aria</button><button id='display' style='display: none'>Display</button><button id='visibility' style='VISIBILITY : HIDDEN'>Visibility</button><div hidden><button id='nested'>Nested</button></div><input id='hidden-input' type='text' style='display:none'><button id='opaque' style='opacity:0'>Opaque</button>",
        )
        .unwrap()
        .with_initial_url("fixture://visibility");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let snapshot = engine.snapshot().unwrap();
    assert_eq!(snapshot.visible_text, "Visible Opaque");
    assert!(!snapshot.text_truncated);

    let nodes = engine.semantic_nodes().unwrap();
    let visible = nodes.iter().find(|node| node.name == "Visible").unwrap();
    assert!(!visible.hidden);
    let opaque = nodes.iter().find(|node| node.name == "Opaque").unwrap();
    assert!(!opaque.hidden);
    for name in ["Hidden", "Aria", "Display", "Visibility", "Nested"] {
        assert!(
            nodes
                .iter()
                .find(|node| node.name == name)
                .is_some_and(|node| node.hidden),
            "expected {name} to be hidden"
        );
    }
    assert!(
        nodes
            .iter()
            .find(|node| node.role == "textbox" && node.name.is_empty())
            .is_some_and(|node| node.hidden)
    );

    let revision_before_rejections = engine.revision();
    for target in ["hidden", "aria", "display", "visibility", "nested"] {
        let result = engine.action(NativeAction::Click {
            target: format!("id={target}"),
        });
        assert!(matches!(
            result,
            Err(NativeEngineError::TargetNotActionable { reason })
                if reason == "hidden targets are not actionable"
        ));
    }
    let result = engine.action(NativeAction::Type {
        target: "id=hidden-input".into(),
        text: "secret".into(),
    });
    assert!(matches!(
        result,
        Err(NativeEngineError::TargetNotActionable { reason })
            if reason == "hidden targets are not actionable"
    ));
    assert_eq!(engine.revision(), revision_before_rejections);
    assert!(
        engine
            .effects_since(revision_before_rejections)
            .unwrap()
            .effects
            .is_empty()
    );
    assert!(
        !engine
            .semantic_nodes()
            .unwrap()
            .into_iter()
            .any(|node| node.focused)
    );
}

#[test]
fn stylesheet_presentation_state_feeds_text_and_actionability() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://styles",
            "<style>/* bounded rules */ .gone, [data-mode=off] { display: none; } #covered { visibility: hidden; } button { display: none; }</style><button id='gone' class='gone'>Gone</button><button id='covered'>Covered</button><button id='attribute' data-mode='off'>Attribute</button><button id='override' style='display: block'>Override</button>",
        )
        .unwrap()
        .with_initial_url("fixture://styles");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    let snapshot = engine.snapshot().unwrap();
    assert_eq!(snapshot.visible_text, "Override");

    let nodes = engine.semantic_nodes().unwrap();
    for name in ["Gone", "Covered", "Attribute"] {
        assert!(
            nodes
                .iter()
                .find(|node| node.name == name)
                .is_some_and(|node| node.hidden),
            "expected {name} to be hidden by stylesheet"
        );
    }
    assert!(
        nodes
            .iter()
            .find(|node| node.name == "Override")
            .is_some_and(|node| !node.hidden)
    );

    let revision_before_rejections = engine.revision();
    assert!(matches!(
        engine.action(NativeAction::Click {
            target: "id=gone".into(),
        }),
        Err(NativeEngineError::TargetNotActionable { .. })
    ));
    assert_eq!(engine.revision(), revision_before_rejections);
    let click = engine
        .action(NativeAction::Click {
            target: "id=override".into(),
        })
        .unwrap();
    assert_eq!(click.revision, revision_before_rejections + 1);
}

#[test]
fn native_descendant_styles_flow_through_visibility_layout_and_paint() {
    let config = NativeEngineConfig::default()
        .with_fixture(
            "fixture://descendant-selectors",
            "<style>main .panel button { display: none; } main .panel .shown { display: block; width: 8px; height: 4px; background-color: red; } main button { display: block; }</style><main><section class='panel'><button id='hidden'>Hidden</button><button id='shown' class='shown'>Shown</button></section></main>",
        )
        .unwrap()
        .with_initial_url("fixture://descendant-selectors");
    let mut engine = NativeEngine::new(config).unwrap();
    engine.initialize().unwrap();

    assert_eq!(engine.snapshot().unwrap().visible_text, "Shown");
    let hidden = engine
        .semantic_nodes()
        .unwrap()
        .into_iter()
        .find(|node| node.name == "Hidden")
        .expect("hidden descendant node");
    let shown = engine
        .semantic_nodes()
        .unwrap()
        .into_iter()
        .find(|node| node.name == "Shown")
        .expect("shown descendant node");
    assert!(hidden.hidden);
    assert!(!shown.hidden);

    let layout = engine.layout().unwrap();
    assert_eq!(layout.box_for(hidden.node_id), None);
    let shown_rect = layout.box_for(shown.node_id).expect("shown layout box");
    let list = engine.display_list().unwrap();
    assert!(list.commands.iter().any(|command| {
        matches!(
            command,
            NativeDisplayCommand::FillRect {
                node_id,
                color,
                ..
            } if *node_id == shown.node_id && *color == NativeColor::RED
        )
    }));
    assert_eq!(
        engine
            .rasterize()
            .unwrap()
            .pixel(shown_rect.x, shown_rect.y),
        Some([255, 0, 0, 255])
    );
}

